-- Voix guerrières : cultures, personnalités et emotes spécifiques
local _, addon = ...
addon.localeData.frFR.racial = {
    GNOME = {
        HEROIC_STRIKE = { "Une expérience réussie demande une frappe précise. Vous savez pourquoi cette arme est lourde ? Elle discute rarement.", "*ajuste une visière de protection minuscule; porte son poids vers l'avant et abat son arme avec vigueur.*", "Si ça marche, j'en publierai les résultats. Certains arguments n'ont pas besoin de seconde phrase.", "*vérifie une attache desserrée sur son armure; engage l'épaule et laisse l'acier finir la démonstration.*" },
        CHARGE = { "Vitesse fois masse ! Ne vérifiez pas le calcul, je suis déjà parti !", "*vérifie une attache desserrée sur son armure; baisse l'épaule et s'élance dans un nuage de poussière.*", "Prière de ne rien toucher pendant l'étalonnage ! J'arrive ! Ce n'est pas une menace, c'est un itinéraire !", "*tapote deux fois un cadran de mesure tordu; traverse une brèche dans un fracas d'armure.*" },
        REND = { "Une expérience réussie demande une frappe précise. Les coutures des armures cachent de petits secrets. Je suis curieux.", "*tapote deux fois un cadran de mesure tordu; fait glisser sa lame dans une ouverture de la garde.*", "Les autres parlent de chaos. Moi, je parle de données. Un tailleur serait scandalisé. Moi, je suis ravi.", "*cache un petit outil dans son gant; retire sa lame et cherche une nouvelle faille.*" },
        HAMSTRING = { "Une expérience réussie demande une frappe précise. Vous enfuir ? Voilà un plan bien fragile.", "*cache un petit outil dans son gant; se baisse vivement sous la garde adverse.*", "Un soupçon de folie n'invalide pas la conception. Je n'aime pas courir deux fois. Une fois suffit.", "*remet ses lunettes de protection en place; fauche bas et reprend immédiatement sa garde.*" },
        THUNDER_CLAP = { "Si l'aiguille se casse, c'était assez bruyant.", "*remet ses lunettes de protection en place; frappe si fort du pied que la poussière bondit.*", "Si ça marche, j'en publierai les résultats. Vous entendez ? Même la terre proteste.", "*griffonne un nombre sur son bouclier en marchant; écarte les bras et laisse une onde sourde courir parmi les rangs.*" },
        CLEAVE = { "La simulation devient fascinante avec de vrais adversaires. Si vous venez côte à côte, vous partagerez les ennuis.", "*griffonne un nombre sur son bouclier en marchant; décrit un vaste arc avec son arme dans la mêlée.*", "Prière de ne rien toucher pendant l'étalonnage ! J'espère que vous avez gardé assez de place. Pas moi.", "*ajuste une visière de protection minuscule; pivote sur un talon et prolonge l'élan d'un second mouvement.*" },
        EXECUTE = { "Une expérience réussie demande une frappe précise. Je vous ai laissé toutes les occasions de battre en retraite.", "*ajuste une visière de protection minuscule; attend un battement de cœur, puis abat un coup décisif.*", "Les autres parlent de chaos. Moi, je parle de données. Les négociations sont terminées.", "*vérifie une attache desserrée sur son armure; resserre sa prise et referme la dernière ouverture.*" },
        SUNDER_ARMOR = { "Une expérience réussie demande une frappe précise. Belle cuirasse. Dommage pour les rivets.", "*vérifie une attache desserrée sur son armure; place le tranchant contre une jointure d'armure.*", "Un soupçon de folie n'invalide pas la conception. Un acier coûteux ne remplace pas une bonne garde.", "*tapote deux fois un cadran de mesure tordu; trace du fil de la lame une ligne entre deux plaques.*" },
        SHIELD_BLOCK = { "La garantie couvre trois ogres. Après, on négocie.", "*tapote deux fois un cadran de mesure tordu; tourne le bord du bouclier pour recevoir le coup.*", "Si ça marche, j'en publierai les résultats. Un bon bouclier écoute avant de répondre.", "*cache un petit outil dans son gant; plante ses bottes au sol sans céder un pouce.*" },
        SHIELD_BASH = { "Une expérience réussie demande une frappe précise. Chut. Voyons si je peux interrompre votre sort.", "*cache un petit outil dans son gant; pousse son bouclier en avant entre deux syllabes.*", "Prière de ne rien toucher pendant l'étalonnage ! Ma réponse à la magie possède une poignée de bois.", "*remet ses lunettes de protection en place; avance d'un pas et tente de percuter sans prévenir.*" },
        TAUNT = { "Une expérience réussie demande une frappe précise. Par ici ! Les ennuis portent mon nom aujourd'hui.", "*remet ses lunettes de protection en place; frappe trois fois la poignée de son arme contre son bouclier.*", "Les autres parlent de chaos. Moi, je parle de données. Les autres sont occupés. Pas moi.", "*griffonne un nombre sur son bouclier en marchant; sort de la ligne et invite les ennemis à approcher.*" },
        BATTLE_SHOUT = { "Le dispositif acoustique est prêt pour les essais. Têtes hautes, rangs serrés ! Personne ne tombe seul !", "*griffonne un nombre sur son bouclier en marchant; bat la mesure avec la poignée contre le bouclier.*", "Un soupçon de folie n'invalide pas la conception. Vous avez des jambes pour tenir et du cœur pour résister. Servez-vous-en !", "*ajuste une visière de protection minuscule; se dresse devant ses alliés et lève la lame.*" },
        DEMORALIZING_SHOUT = { "Le dispositif acoustique est prêt pour les essais. Les premiers tremblent déjà. Les derniers suivront !", "*ajuste une visière de protection minuscule; pousse un cri profond et rugueux du fond de la poitrine.*", "Si ça marche, j'en publierai les résultats. Regardez autour de vous. Pour qui vous battez-vous encore ?", "*vérifie une attache desserrée sur son armure; désigne de sa lame les lignes ennemies vacillantes.*" },
        REVENGE = { "Une expérience réussie demande une frappe précise. Merci pour l'occasion. Je vous la rends aussitôt.", "*vérifie une attache desserrée sur son armure; dévie une arme et frappe dans la brèche.*", "Prière de ne rien toucher pendant l'étalonnage ! J'oublie les visages. Jamais les coups.", "*tapote deux fois un cadran de mesure tordu; passe directement de la parade à la riposte.*" },
        OVERPOWER = { "Une expérience réussie demande une frappe précise. Voilà une faille. Comme c'est généreux de votre part.", "*tapote deux fois un cadran de mesure tordu; esquive le coup manqué et saisit l'angle ouvert.*", "Les autres parlent de chaos. Moi, je parle de données. Manquez-moi une fois, vous m'invitez à entrer.", "*cache un petit outil dans son gant; transforme un faux pas adverse en riposte éclair.*" },
        MORTAL_STRIKE = { "Une expérience réussie demande une frappe précise. Je ne garde rien pour une seconde tentative.", "*cache un petit outil dans son gant; saisit son arme à deux mains et engage tout son poids.*", "Un soupçon de folie n'invalide pas la conception. Certains duels se règlent en paroles. Pas celui-ci.", "*remet ses lunettes de protection en place; avance et conduit l'acier avec une précision implacable.*" },
        WHIRLWIND = { "La simulation devient fascinante avec de vrais adversaires. Mettez-vous donc en cercle. Cela m'arrange.", "*remet ses lunettes de protection en place; tourne dans la mêlée, l'arme tendue à bout de bras.*", "Si ça marche, j'en publierai les résultats. J'aime partager. Aujourd'hui, c'est de l'acier.", "*griffonne un nombre sur son bouclier en marchant; fait chanter la lame dans un large mouvement circulaire.*" },
        BLOODTHIRST = { "Une surcharge contrôlée n'est pas une panne. Le pouls s'emballe. La main reste sûre.", "*griffonne un nombre sur son bouclier en marchant; expire brusquement et poursuit son assaut sans relâche.*", "Prière de ne rien toucher pendant l'étalonnage ! La colère ne rend pas mes coups imprécis.", "*ajuste une visière de protection minuscule; se rue en avant, les yeux sauvages, la prise parfaitement mesurée.*" },
        INTERCEPT = { "L'accélération a été calculée à l'avance, naturellement. Une avance n'est qu'un temps emprunté.", "*ajuste une visière de protection minuscule; jaillit de la mêlée et coupe toute retraite.*", "Les autres parlent de chaos. Moi, je parle de données. Vous courez ? Parfait, j'avais besoin d'exercice.", "*vérifie une attache desserrée sur son armure; bondit de sa position et atterrit sur le chemin de la fuite.*" },
        PUMMEL = { "Une expérience réussie demande une frappe précise. Trop de paroles. Pas assez de garde.", "*vérifie une attache desserrée sur son armure; rompt le geste d'incantation d'un coup sec et précis.*", "Un soupçon de folie n'invalide pas la conception. Vous vouliez ajouter quelque chose ? Non ? Bien.", "*tapote deux fois un cadran de mesure tordu; désorganise le mouvement du bras d'un petit coup.*" },
        SWEEPING_STRIKES = { "La simulation devient fascinante avec de vrais adversaires. Pourquoi faire la moitié du travail quand toute une bataille nous attend ?", "*tapote deux fois un cadran de mesure tordu; prolonge le premier coup en un second arc fluide.*", "Si ça marche, j'en publierai les résultats. Plus d'ennemis ? Moins de déplacements.", "*cache un petit outil dans son gant; poursuit le mouvement de la lame à travers la mêlée.*" },
        DEATH_WISH = { "Une surcharge contrôlée n'est pas une panne. La raison a donné son avis. Je ne suis pas d'accord.", "*cache un petit outil dans son gant; relâche un instant sa prise et choisit l'attaque.*", "Prière de ne rien toucher pendant l'étalonnage ! Je connais le risque. Eux, peut-être pas.", "*remet ses lunettes de protection en place; jette un dernier regard à sa garde avant de bondir.*" },
        RECKLESSNESS = { "Une surcharge contrôlée n'est pas une panne. La prudence, c'était hier. Aujourd'hui, on agit.", "*remet ses lunettes de protection en place; rejette l'hésitation sans lâcher son arme.*", "Les autres parlent de chaos. Moi, je parle de données. Vous pourrez me faire la morale demain. S'il y a un demain.", "*griffonne un nombre sur son bouclier en marchant; engage tout son corps dans une suite de coups furieux.*" },
        LAST_STAND = { "Mes précautions de sécurité servent enfin à quelque chose. Jusqu'ici. Pas un pas de plus.", "*griffonne un nombre sur son bouclier en marchant; se relève péniblement et lève de nouveau le bouclier.*", "Un soupçon de folie n'invalide pas la conception. Je tiens encore debout. Voilà ma réponse.", "*ajuste une visière de protection minuscule; replace ses jambes tremblantes dans la brèche.*" },
        SHIELD_WALL = { "Mes précautions de sécurité servent enfin à quelque chose. Derrière moi ! Pas d'héroïsme solitaire !", "*ajuste une visière de protection minuscule; ramène le bouclier contre soi et serre la ligne alliée.*", "Si ça marche, j'en publierai les résultats. Qui veut passer devra avoir de la patience.", "*vérifie une attache desserrée sur son armure; ferme la dernière brèche entre le bouclier et l'armure.*" },
        RETALIATION = { "Une expérience réussie demande une frappe précise. Qui frappe doit apprécier l'écho.", "*vérifie une attache desserrée sur son armure; entrouvre la garde et répond à chaque coup par l'acier.*", "Prière de ne rien toucher pendant l'étalonnage ! Venez donc. J'ai un instant pour chacun.", "*tapote deux fois un cadran de mesure tordu; ancre les pieds et attend les coups impatients.*" },
        MOCKING_BLOW = { "Une expérience réussie demande une frappe précise. Vous êtes dangereux ou simplement bruyant ?", "*tapote deux fois un cadran de mesure tordu; abaisse trop ostensiblement la pointe et attire l'ennemi.*", "Les autres parlent de chaos. Moi, je parle de données. Pardon. Je vous ai pris pour un mannequin d'entraînement.", "*cache un petit outil dans son gant; porte une petite taille insolente et sourit au-dessus du bouclier.*" },
        BERSERKER_RAGE = { "Une surcharge contrôlée n'est pas une panne. La peur ? Pas de place pour elle aujourd'hui.", "*cache un petit outil dans son gant; roule les épaules comme pour se débarrasser d'un poids invisible.*", "Un soupçon de folie n'invalide pas la conception. La peur peut attendre dehors. Ma fureur entre.", "*remet ses lunettes de protection en place; expire brutalement et fixe le combat sans ciller.*" },
        BLOODRAGE = { "Une surcharge contrôlée n'est pas une panne. La douleur est un message. Je répondrai plus tard.", "*remet ses lunettes de protection en place; frappe son torse du poing et rassemble son ardeur.*", "Si ça marche, j'en publierai les résultats. Le cœur bat encore. Cela suffit comme explication.", "*griffonne un nombre sur son bouclier en marchant; serre les dents et raidit les épaules sous l'armure.*" },
        DISARM = { "Une expérience réussie demande une frappe précise. Jolie épée. Puis-je la voir un instant ?", "*griffonne un nombre sur son bouclier en marchant; tente d'arracher l'arme adverse d'une brève torsion.*", "Prière de ne rien toucher pendant l'étalonnage ! Voyons si vous êtes aussi bavard sans arme.", "*ajuste une visière de protection minuscule; tente de saisir le bras armé et de détourner le manche hors de sa ligne.*" },
        INTIMIDATING_SHOUT = { "Le dispositif acoustique est prêt pour les essais. Fuyez tant que vous connaissez encore la route !", "*ajuste une visière de protection minuscule; lance un rugissement féroce au-dessus des têtes ennemies.*", "Les autres parlent de chaos. Moi, je parle de données. C'était mon avertissement poli. Le prochain sera d'acier.", "*vérifie une attache desserrée sur son armure; frappe le bouclier et découvre les dents.*" },
        CHALLENGING_SHOUT = { "Le dispositif acoustique est prêt pour les essais. TOUS SUR MOI ! J'ai de la place pour toutes vos rancunes !", "*vérifie une attache desserrée sur son armure; écarte les bras et défie la ligne entière.*", "Un soupçon de folie n'invalide pas la conception. Laissez les autres ! Aujourd'hui, je suis votre problème !", "*tapote deux fois un cadran de mesure tordu; martèle son bouclier et hurle aux assaillants.*" },
        SLAM = { "Une expérience réussie demande une frappe précise. Ce n'est pas un marteau. Vous ne sentirez guère la différence.", "*tapote deux fois un cadran de mesure tordu; lève son arme au-dessus de l'épaule et l'abat de tout son poids.*", "Si ça marche, j'en publierai les résultats. Un coup net vaut cinq coups timides.", "*cache un petit outil dans son gant; suspend un instant le mouvement, puis frappe lourdement.*" },
