        SHIELD_SLAM = { "Une expérience réussie demande une frappe précise. Un bouclier ferme aussi les portes. Souvent à hauteur de visage.", "*remet ses lunettes de protection en place; arrache le bouclier de sa garde et projette le bord en avant.*", "Les autres parlent de chaos. Moi, je parle de données. Qui a prétendu que la défense devait être polie ?", "*griffonne un nombre sur son bouclier en marchant; bondit d'un pas et laisse parler son bouclier.*" },
        CONCUSSION_BLOW = { "Une expérience réussie demande une frappe précise. Je vais essayer de vous déconcentrer.", "*griffonne un nombre sur son bouclier en marchant; tente de porter un coup lourd entre deux mouvements adverses.*", "Un soupçon de folie n'invalide pas la conception. Je vais essayer d’offrir un instant de silence à tout le monde.", "*ajuste une visière de protection minuscule; raccourcit sa prise et tente de frapper avec une force surprenante.*" },
        VICTORY_RUSH = { "L'accélération a été calculée à l'avance, naturellement. Un de moins. Les autres tiennent encore debout.", "*ajuste une visière de protection minuscule; profite de son regain d'énergie pour repartir à l'assaut.*", "Si ça marche, j'en publierai les résultats. Nous fêterons cela plus tard. Quelque chose bouge encore.", "*vérifie une attache desserrée sur son armure; se frappe une fois la poitrine et avance aussitôt.*" },
        BATTLE_STANCE = { "La simulation devient fascinante avec de vrais adversaires. Deux pieds bien placés séparent le courage de la sottise.", "*vérifie une attache desserrée sur son armure; plante les pieds à largeur d'épaules et fait rouler sa lame.*", "Prière de ne rien toucher pendant l'étalonnage ! Je reste prêt. Au reste du monde de décider.", "*tapote deux fois un cadran de mesure tordu; répartit son poids entre le bras de bouclier et la main armée.*" },
        DEFENSIVE_STANCE = { "Mes précautions de sécurité servent enfin à quelque chose. Pour atteindre les miens, il faudra convaincre mon bouclier.", "*tapote deux fois un cadran de mesure tordu; élargit ses appuis et lève le bouclier devant ses alliés.*", "Les autres parlent de chaos. Moi, je parle de données. Ce n'est pas le cri le plus fort qui gagnera aujourd'hui.", "*cache un petit outil dans son gant; abaisse son centre de gravité et devient un mur derrière sa garde.*" },
        BERSERKER_STANCE = { "Une surcharge contrôlée n'est pas une panne. Qui a dit que la colère rend aveugle n'a jamais vraiment regardé.", "*cache un petit outil dans son gant; inspire profondément et prend une posture féroce.*", "Un soupçon de folie n'invalide pas la conception. Le monde est soudain très simple : en avant.", "*remet ses lunettes de protection en place; relâche les épaules, abaisse son arme, puis la relève vivement.*" },
        PIERCING_HOWL = { "Le dispositif acoustique est prêt pour les essais. Si vous m'entendez, c'est déjà trop tard.", "*remet ses lunettes de protection en place; pousse un hurlement qui perce tout le vacarme alentour.*", "Si ça marche, j'en publierai les résultats. Non, ce n'était pas une meute de loups. Seulement moi.", "*griffonne un nombre sur son bouclier en marchant; renverse la tête et laisse monter un long cri rauque.*" },
        SPEARING_STRIKE = { "Une expérience réussie demande une frappe précise. La brèche est étroite. Ma pointe ne l'est pas.", "*griffonne un nombre sur son bouclier en marchant; avance droit devant, l'arme tendue.*", "Prière de ne rien toucher pendant l'étalonnage ! L'armure est solide. Les angles sont plus forts.", "*ajuste une visière de protection minuscule; tourne le poignet vers la faille et pousse la pointe.*" },
