        BATTLE_SHOUT = { "Aujourd'hui, nous marchons les uns pour les autres, pas pour une bannière !", "*passe le pouce sur une ancienne entaille de sa poignée; bat la mesure avec la poignée contre le bouclier.*", "Sous cette armure, il reste une promesse. Vous avez des jambes pour tenir et du cœur pour résister. Servez-vous-en !", "*redresse le blason usé sur son bouclier; se dresse devant ses alliés et lève la lame.*" },
        DEMORALIZING_SHOUT = { "Parfois, une voix doit remplacer tout un étendard. Les premiers tremblent déjà. Les derniers suivront !", "*redresse le blason usé sur son bouclier; pousse un cri profond et rugueux du fond de la poitrine.*", "Les autres comptent sur moi. Je ne les trahirai pas. Regardez autour de vous. Pour qui vous battez-vous encore ?", "*vérifie la formation alliée d'un regard vif; désigne de sa lame les lignes ennemies vacillantes.*" },
        REVENGE = { "Pendant ma formation, on appelait ça une leçon.", "*vérifie la formation alliée d'un regard vif; dévie une arme et frappe dans la brèche.*", "Garder sa tenue, même quand personne ne regarde. J'oublie les visages. Jamais les coups.", "*resserre une lanière de cuir sur son avant-bras; passe directement de la parade à la riposte.*" },
        OVERPOWER = { "L'entraînement fut rude. Il porte enfin ses fruits. Voilà une faille. Comme c'est généreux de votre part.", "*resserre une lanière de cuir sur son avant-bras; esquive le coup manqué et saisit l'angle ouvert.*", "Un plan de bataille survit mieux quand quelqu'un le défend. Manquez-moi une fois, vous m'invitez à entrer.", "*adresse un bref signe de tête à un compagnon; transforme un faux pas adverse en riposte éclair.*" },
        MORTAL_STRIKE = { "L'entraînement fut rude. Il porte enfin ses fruits. Je ne garde rien pour une seconde tentative.", "*adresse un bref signe de tête à un compagnon; saisit son arme à deux mains et engage tout son poids.*", "Sous cette armure, il reste une promesse. Certains duels se règlent en paroles. Pas celui-ci.", "*replace son casque d'un geste habitué; avance et conduit l'acier avec une précision implacable.*" },
        WHIRLWIND = { "Lire le terrain avant de donner l'ordre d'avancer. Mettez-vous donc en cercle. Cela m'arrange.", "*replace son casque d'un geste habitué; tourne dans la mêlée, l'arme tendue à bout de bras.*", "Les autres comptent sur moi. Je ne les trahirai pas. J'aime partager. Aujourd'hui, c'est de l'acier.", "*passe le pouce sur une ancienne entaille de sa poignée; fait chanter la lame dans un large mouvement circulaire.*" },
        BLOODTHIRST = { "La colère sans discipline frappe les mauvaises personnes. Le pouls s'emballe. La main reste sûre.", "*passe le pouce sur une ancienne entaille de sa poignée; expire brusquement et poursuit son assaut sans relâche.*", "Garder sa tenue, même quand personne ne regarde. La colère ne rend pas mes coups imprécis.", "*redresse le blason usé sur son bouclier; se rue en avant, les yeux sauvages, la prise parfaitement mesurée.*" },
        INTERCEPT = { "Les ordres sont utiles. Montrer la voie vaut mieux. Une avance n'est qu'un temps emprunté.", "*redresse le blason usé sur son bouclier; jaillit de la mêlée et coupe toute retraite.*", "Un plan de bataille survit mieux quand quelqu'un le défend. Vous courez ? Parfait, j'avais besoin d'exercice.", "*vérifie la formation alliée d'un regard vif; bondit de sa position et atterrit sur le chemin de la fuite.*" },
        PUMMEL = { "L'entraînement fut rude. Il porte enfin ses fruits. Trop de paroles. Pas assez de garde.", "*vérifie la formation alliée d'un regard vif; rompt le geste d'incantation d'un coup sec et précis.*", "Sous cette armure, il reste une promesse. Vous vouliez ajouter quelque chose ? Non ? Bien.", "*resserre une lanière de cuir sur son avant-bras; désorganise le mouvement du bras d'un petit coup.*" },
        SWEEPING_STRIKES = { "Lire le terrain avant de donner l'ordre d'avancer. Pourquoi faire la moitié du travail quand toute une bataille nous attend ?", "*resserre une lanière de cuir sur son avant-bras; prolonge le premier coup en un second arc fluide.*", "Les autres comptent sur moi. Je ne les trahirai pas. Plus d'ennemis ? Moins de déplacements.", "*adresse un bref signe de tête à un compagnon; poursuit le mouvement de la lame à travers la mêlée.*" },
        DEATH_WISH = { "La colère sans discipline frappe les mauvaises personnes. La raison a donné son avis. Je ne suis pas d'accord.", "*adresse un bref signe de tête à un compagnon; relâche un instant sa prise et choisit l'attaque.*", "Garder sa tenue, même quand personne ne regarde. Je connais le risque. Eux, peut-être pas.", "*replace son casque d'un geste habitué; jette un dernier regard à sa garde avant de bondir.*" },
        RECKLESSNESS = { "La colère sans discipline frappe les mauvaises personnes. La prudence, c'était hier. Aujourd'hui, on agit.", "*replace son casque d'un geste habitué; rejette l'hésitation sans lâcher son arme.*", "Un plan de bataille survit mieux quand quelqu'un le défend. Vous pourrez me faire la morale demain. S'il y a un demain.", "*passe le pouce sur une ancienne entaille de sa poignée; engage tout son corps dans une suite de coups furieux.*" },
        LAST_STAND = { "Une ligne n'est perdue que si le dernier défenseur renonce.", "*passe le pouce sur une ancienne entaille de sa poignée; se relève péniblement et lève de nouveau le bouclier.*", "Sous cette armure, il reste une promesse. Je tiens encore debout. Voilà ma réponse.", "*redresse le blason usé sur son bouclier; replace ses jambes tremblantes dans la brèche.*" },
        SHIELD_WALL = { "La ligne est à nous tant que nous restons unis. Derrière moi ! Pas d'héroïsme solitaire !", "*redresse le blason usé sur son bouclier; ramène le bouclier contre soi et serre la ligne alliée.*", "Les autres comptent sur moi. Je ne les trahirai pas. Qui veut passer devra avoir de la patience.", "*vérifie la formation alliée d'un regard vif; ferme la dernière brèche entre le bouclier et l'armure.*" },
        RETALIATION = { "L'entraînement fut rude. Il porte enfin ses fruits. Qui frappe doit apprécier l'écho.", "*vérifie la formation alliée d'un regard vif; entrouvre la garde et répond à chaque coup par l'acier.*", "Garder sa tenue, même quand personne ne regarde. Venez donc. J'ai un instant pour chacun.", "*resserre une lanière de cuir sur son avant-bras; ancre les pieds et attend les coups impatients.*" },
        MOCKING_BLOW = { "L'entraînement fut rude. Il porte enfin ses fruits. Vous êtes dangereux ou simplement bruyant ?", "*resserre une lanière de cuir sur son avant-bras; abaisse trop ostensiblement la pointe et attire l'ennemi.*", "Un plan de bataille survit mieux quand quelqu'un le défend. Pardon. Je vous ai pris pour un mannequin d'entraînement.", "*adresse un bref signe de tête à un compagnon; porte une petite taille insolente et sourit au-dessus du bouclier.*" },
        BERSERKER_RAGE = { "La colère sans discipline frappe les mauvaises personnes. La peur ? Pas de place pour elle aujourd'hui.", "*adresse un bref signe de tête à un compagnon; roule les épaules comme pour se débarrasser d'un poids invisible.*", "Sous cette armure, il reste une promesse. La peur peut attendre dehors. Ma fureur entre.", "*replace son casque d'un geste habitué; expire brutalement et fixe le combat sans ciller.*" },
        BLOODRAGE = { "La colère sans discipline frappe les mauvaises personnes. La douleur est un message. Je répondrai plus tard.", "*replace son casque d'un geste habitué; frappe son torse du poing et rassemble son ardeur.*", "Les autres comptent sur moi. Je ne les trahirai pas. Le cœur bat encore. Cela suffit comme explication.", "*passe le pouce sur une ancienne entaille de sa poignée; serre les dents et raidit les épaules sous l'armure.*" },
        DISARM = { "L'entraînement fut rude. Il porte enfin ses fruits. Jolie épée. Puis-je la voir un instant ?", "*passe le pouce sur une ancienne entaille de sa poignée; tente d'arracher l'arme adverse d'une brève torsion.*", "Garder sa tenue, même quand personne ne regarde. Voyons si vous êtes aussi bavard sans arme.", "*redresse le blason usé sur son bouclier; tente de saisir le bras armé et de détourner le manche hors de sa ligne.*" },
        INTIMIDATING_SHOUT = { "Parfois, une voix doit remplacer tout un étendard. Fuyez tant que vous connaissez encore la route !", "*redresse le blason usé sur son bouclier; lance un rugissement féroce au-dessus des têtes ennemies.*", "Un plan de bataille survit mieux quand quelqu'un le défend. C'était mon avertissement poli. Le prochain sera d'acier.", "*vérifie la formation alliée d'un regard vif; frappe le bouclier et découvre les dents.*" },
        CHALLENGING_SHOUT = { "Parfois, une voix doit remplacer tout un étendard. TOUS SUR MOI ! J'ai de la place pour toutes vos rancunes !", "*vérifie la formation alliée d'un regard vif; écarte les bras et défie la ligne entière.*", "Sous cette armure, il reste une promesse. Laissez les autres ! Aujourd'hui, je suis votre problème !", "*resserre une lanière de cuir sur son avant-bras; martèle son bouclier et hurle aux assaillants.*" },
        SLAM = { "L'entraînement fut rude. Il porte enfin ses fruits. Ce n'est pas un marteau. Vous ne sentirez guère la différence.", "*resserre une lanière de cuir sur son avant-bras; lève son arme au-dessus de l'épaule et l'abat de tout son poids.*", "Les autres comptent sur moi. Je ne les trahirai pas. Un coup net vaut cinq coups timides.", "*adresse un bref signe de tête à un compagnon; suspend un instant le mouvement, puis frappe lourdement.*" },
        DEVASTATE = { "L'entraînement fut rude. Il porte enfin ses fruits. Déjà desserré ? Terminons le travail.", "*adresse un bref signe de tête à un compagnon; frappe une section d'armure déjà fragilisée.*", "Garder sa tenue, même quand personne ne regarde. Votre forgeron a visiblement économisé au mauvais endroit.", "*replace son casque d'un geste habitué; tapote une jointure découverte, puis frappe de nouveau.*" },
        SHIELD_SLAM = { "L'entraînement fut rude. Il porte enfin ses fruits. Un bouclier ferme aussi les portes. Souvent à hauteur de visage.", "*replace son casque d'un geste habitué; arrache le bouclier de sa garde et projette le bord en avant.*", "Un plan de bataille survit mieux quand quelqu'un le défend. Qui a prétendu que la défense devait être polie ?", "*passe le pouce sur une ancienne entaille de sa poignée; bondit d'un pas et laisse parler son bouclier.*" },
        CONCUSSION_BLOW = { "L'entraînement fut rude. Il porte enfin ses fruits. Je vais essayer de vous déconcentrer.", "*passe le pouce sur une ancienne entaille de sa poignée; tente de porter un coup lourd entre deux mouvements adverses.*", "Sous cette armure, il reste une promesse. Je vais essayer d’offrir un instant de silence à tout le monde.", "*redresse le blason usé sur son bouclier; raccourcit sa prise et tente de frapper avec une force surprenante.*" },
        VICTORY_RUSH = { "Les ordres sont utiles. Montrer la voie vaut mieux. Un de moins. Les autres tiennent encore debout.", "*redresse le blason usé sur son bouclier; profite de son regain d'énergie pour repartir à l'assaut.*", "Les autres comptent sur moi. Je ne les trahirai pas. Nous fêterons cela plus tard. Quelque chose bouge encore.", "*vérifie la formation alliée d'un regard vif; se frappe une fois la poitrine et avance aussitôt.*" },
        BATTLE_STANCE = { "Lire le terrain avant de donner l'ordre d'avancer. Deux pieds bien placés séparent le courage de la sottise.", "*vérifie la formation alliée d'un regard vif; plante les pieds à largeur d'épaules et fait rouler sa lame.*", "Garder sa tenue, même quand personne ne regarde. Je reste prêt. Au reste du monde de décider.", "*resserre une lanière de cuir sur son avant-bras; répartit son poids entre le bras de bouclier et la main armée.*" },
        DEFENSIVE_STANCE = { "La ligne est à nous tant que nous restons unis. Pour atteindre les miens, il faudra convaincre mon bouclier.", "*resserre une lanière de cuir sur son avant-bras; élargit ses appuis et lève le bouclier devant ses alliés.*", "Un plan de bataille survit mieux quand quelqu'un le défend. Ce n'est pas le cri le plus fort qui gagnera aujourd'hui.", "*adresse un bref signe de tête à un compagnon; abaisse son centre de gravité et devient un mur derrière sa garde.*" },
        BERSERKER_STANCE = { "La colère sans discipline frappe les mauvaises personnes. Qui a dit que la colère rend aveugle n'a jamais vraiment regardé.", "*adresse un bref signe de tête à un compagnon; inspire profondément et prend une posture féroce.*", "Sous cette armure, il reste une promesse. Le monde est soudain très simple : en avant.", "*replace son casque d'un geste habitué; relâche les épaules, abaisse son arme, puis la relève vivement.*" },
        PIERCING_HOWL = { "Parfois, une voix doit remplacer tout un étendard. Si vous m'entendez, c'est déjà trop tard.", "*replace son casque d'un geste habitué; pousse un hurlement qui perce tout le vacarme alentour.*", "Les autres comptent sur moi. Je ne les trahirai pas. Non, ce n'était pas une meute de loups. Seulement moi.", "*passe le pouce sur une ancienne entaille de sa poignée; renverse la tête et laisse monter un long cri rauque.*" },
        SPEARING_STRIKE = { "L'entraînement fut rude. Il porte enfin ses fruits. La brèche est étroite. Ma pointe ne l'est pas.", "*passe le pouce sur une ancienne entaille de sa poignée; avance droit devant, l'arme tendue.*", "Garder sa tenue, même quand personne ne regarde. L'armure est solide. Les angles sont plus forts.", "*redresse le blason usé sur son bouclier; tourne le poignet vers la faille et pousse la pointe.*" },
        TACTICAL_MASTERY = { "Lire le terrain avant de donner l'ordre d'avancer. Entre le courage et la sottise, il y a de bons appuis.", "*redresse le blason usé sur son bouclier; ajuste sa position d'un rien et garde le champ de bataille en vue.*", "Un plan de bataille survit mieux quand quelqu'un le défend. Un champ de bataille ne se joue pas aux dés. Il se lit.", "*vérifie la formation alliée d'un regard vif; observe les chemins, les ennemis et les retraites sans abaisser son arme.*" },
    },
    DWARF = {
        HEROIC_STRIKE = { "Par la barbe de ma grand-mère, voilà du bon travail ! Vous savez pourquoi cette arme est lourde ? Elle discute rarement.", "*frappe du doigt le bord bosselé de son bouclier; porte son poids vers l'avant et abat son arme avec vigueur.*", "Nous en parlerons autour d'une chope. Peut-être. Certains arguments n'ont pas besoin de seconde phrase.", "*crache résolument dans ses gants; engage l'épaule et laisse l'acier finir la démonstration.*" },
        CHARGE = { "Ces bottes ne connaissent qu'une direction : devant. Si le chemin est fermé, je prends la ligne droite.", "*crache résolument dans ses gants; baisse l'épaule et s'élance dans un nuage de poussière.*", "Une enclume ne se plaint pas d'un bon coup de marteau. J'arrive ! Ce n'est pas une menace, c'est un itinéraire !", "*enfonce le casque au-dessus de ses sourcils broussailleux; traverse une brèche dans un fracas d'armure.*" },
        REND = { "Par la barbe de ma grand-mère, voilà du bon travail ! Les coutures des armures cachent de petits secrets. Je suis curieux.", "*enfonce le casque au-dessus de ses sourcils broussailleux; fait glisser sa lame dans une ouverture de la garde.*", "Les genoux qui tremblent ? Pas dans cette famille. Un tailleur serait scandalisé. Moi, je suis ravi.", "*plante ses bottes comme sur une pente de montagne; retire sa lame et cherche une nouvelle faille.*" },
        HAMSTRING = { "Par la barbe de ma grand-mère, voilà du bon travail ! Vous enfuir ? Voilà un plan bien fragile.", "*plante ses bottes comme sur une pente de montagne; se baisse vivement sous la garde adverse.*", "La pierre se souvient de ceux qui ont cédé devant elle. Je n'aime pas courir deux fois. Une fois suffit.", "*repousse une mèche de barbe égarée; fauche bas et reprend immédiatement sa garde.*" },
        THUNDER_CLAP = { "Par la barbe de ma grand-mère, voilà du bon travail ! Quand le sol tremble, plus besoin de tambour.", "*repousse une mèche de barbe égarée; frappe si fort du pied que la poussière bondit.*", "Nous en parlerons autour d'une chope. Peut-être. Vous entendez ? Même la terre proteste.", "*frappe sa cuirasse du pommeau de son arme; écarte les bras et laisse une onde sourde courir parmi les rangs.*" },
        CLEAVE = { "Mon grand-père appelait ça le bon sens des montagnes. Si vous venez côte à côte, vous partagerez les ennuis.", "*frappe sa cuirasse du pommeau de son arme; décrit un vaste arc avec son arme dans la mêlée.*", "Une enclume ne se plaint pas d'un bon coup de marteau. J'espère que vous avez gardé assez de place. Pas moi.", "*frappe du doigt le bord bosselé de son bouclier; pivote sur un talon et prolonge l'élan d'un second mouvement.*" },
        EXECUTE = { "Par la barbe de ma grand-mère, voilà du bon travail ! Je vous ai laissé toutes les occasions de battre en retraite.", "*frappe du doigt le bord bosselé de son bouclier; attend un battement de cœur, puis abat un coup décisif.*", "Les genoux qui tremblent ? Pas dans cette famille. Les négociations sont terminées.", "*crache résolument dans ses gants; resserre sa prise et referme la dernière ouverture.*" },
        SUNDER_ARMOR = { "Par la barbe de ma grand-mère, voilà du bon travail ! Belle cuirasse. Dommage pour les rivets.", "*crache résolument dans ses gants; place le tranchant contre une jointure d'armure.*", "La pierre se souvient de ceux qui ont cédé devant elle. Un acier coûteux ne remplace pas une bonne garde.", "*enfonce le casque au-dessus de ses sourcils broussailleux; trace du fil de la lame une ligne entre deux plaques.*" },
        SHIELD_BLOCK = { "La montagne ne demande pas la force du vent. Il faudra frapper à la porte. Mon bouclier reste fermé.", "*enfonce le casque au-dessus de ses sourcils broussailleux; tourne le bord du bouclier pour recevoir le coup.*", "Nous en parlerons autour d'une chope. Peut-être. Un bon bouclier écoute avant de répondre.", "*plante ses bottes comme sur une pente de montagne; plante ses bottes au sol sans céder un pouce.*" },
        SHIELD_BASH = { "Par la barbe de ma grand-mère, voilà du bon travail ! Chut. Voyons si je peux interrompre votre sort.", "*plante ses bottes comme sur une pente de montagne; pousse son bouclier en avant entre deux syllabes.*", "Une enclume ne se plaint pas d'un bon coup de marteau. Ma réponse à la magie possède une poignée de bois.", "*repousse une mèche de barbe égarée; avance d'un pas et tente de percuter sans prévenir.*" },
        TAUNT = { "Par la barbe de ma grand-mère, voilà du bon travail ! Par ici ! Les ennuis portent mon nom aujourd'hui.", "*repousse une mèche de barbe égarée; frappe trois fois la poignée de son arme contre son bouclier.*", "Les genoux qui tremblent ? Pas dans cette famille. Les autres sont occupés. Pas moi.", "*frappe sa cuirasse du pommeau de son arme; sort de la ligne et invite les ennemis à approcher.*" },
