        LAST_STAND = { "La montagne ne demande pas la force du vent. Jusqu'ici. Pas un pas de plus.", "*frappe sa cuirasse du pommeau de son arme; se relève péniblement et lève de nouveau le bouclier.*", "La pierre se souvient de ceux qui ont cédé devant elle. Je tiens encore debout. Voilà ma réponse.", "*frappe du doigt le bord bosselé de son bouclier; replace ses jambes tremblantes dans la brèche.*" },
        SHIELD_WALL = { "Ce mur est plus vieux que votre arbre généalogique et tient mieux !", "*frappe du doigt le bord bosselé de son bouclier; ramène le bouclier contre soi et serre la ligne alliée.*", "Nous en parlerons autour d'une chope. Peut-être. Qui veut passer devra avoir de la patience.", "*crache résolument dans ses gants; ferme la dernière brèche entre le bouclier et l'armure.*" },
        RETALIATION = { "Par la barbe de ma grand-mère, voilà du bon travail ! Qui frappe doit apprécier l'écho.", "*crache résolument dans ses gants; entrouvre la garde et répond à chaque coup par l'acier.*", "Une enclume ne se plaint pas d'un bon coup de marteau. Venez donc. J'ai un instant pour chacun.", "*enfonce le casque au-dessus de ses sourcils broussailleux; ancre les pieds et attend les coups impatients.*" },
        MOCKING_BLOW = { "Par la barbe de ma grand-mère, voilà du bon travail ! Vous êtes dangereux ou simplement bruyant ?", "*enfonce le casque au-dessus de ses sourcils broussailleux; abaisse trop ostensiblement la pointe et attire l'ennemi.*", "Les genoux qui tremblent ? Pas dans cette famille. Pardon. Je vous ai pris pour un mannequin d'entraînement.", "*plante ses bottes comme sur une pente de montagne; porte une petite taille insolente et sourit au-dessus du bouclier.*" },
        BERSERKER_RAGE = { "Par l'enclume ! Qui a bu ma dernière chope ?", "*plante ses bottes comme sur une pente de montagne; roule les épaules comme pour se débarrasser d'un poids invisible.*", "La pierre se souvient de ceux qui ont cédé devant elle. La peur peut attendre dehors. Ma fureur entre.", "*repousse une mèche de barbe égarée; expire brutalement et fixe le combat sans ciller.*" },
        BLOODRAGE = { "Ma colère monte de loin, à hauteur de tonneau. La douleur est un message. Je répondrai plus tard.", "*repousse une mèche de barbe égarée; frappe son torse du poing et rassemble son ardeur.*", "Nous en parlerons autour d'une chope. Peut-être. Le cœur bat encore. Cela suffit comme explication.", "*frappe sa cuirasse du pommeau de son arme; serre les dents et raidit les épaules sous l'armure.*" },
        DISARM = { "Jolie épée. Mon forgeron aurait tout de même repris le travail.", "*frappe sa cuirasse du pommeau de son arme; tente d'arracher l'arme adverse d'une brève torsion.*", "Une enclume ne se plaint pas d'un bon coup de marteau. Voyons si vous êtes aussi bavard sans arme.", "*frappe du doigt le bord bosselé de son bouclier; tente de saisir le bras armé et de détourner le manche hors de sa ligne.*" },
        INTIMIDATING_SHOUT = { "Qui n'entend pas ça depuis la taverne n'a plus d'espoir ! Fuyez tant que vous connaissez encore la route !", "*frappe du doigt le bord bosselé de son bouclier; lance un rugissement féroce au-dessus des têtes ennemies.*", "Les genoux qui tremblent ? Pas dans cette famille. C'était mon avertissement poli. Le prochain sera d'acier.", "*crache résolument dans ses gants; frappe le bouclier et découvre les dents.*" },
        CHALLENGING_SHOUT = { "Qui n'entend pas ça depuis la taverne n'a plus d'espoir ! TOUS SUR MOI ! J'ai de la place pour toutes vos rancunes !", "*crache résolument dans ses gants; écarte les bras et défie la ligne entière.*", "La pierre se souvient de ceux qui ont cédé devant elle. Laissez les autres ! Aujourd'hui, je suis votre problème !", "*enfonce le casque au-dessus de ses sourcils broussailleux; martèle son bouclier et hurle aux assaillants.*" },
        SLAM = { "Par la barbe de ma grand-mère, voilà du bon travail ! Ce n'est pas un marteau. Vous ne sentirez guère la différence.", "*enfonce le casque au-dessus de ses sourcils broussailleux; lève son arme au-dessus de l'épaule et l'abat de tout son poids.*", "Nous en parlerons autour d'une chope. Peut-être. Un coup net vaut cinq coups timides.", "*plante ses bottes comme sur une pente de montagne; suspend un instant le mouvement, puis frappe lourdement.*" },
        DEVASTATE = { "Par la barbe de ma grand-mère, voilà du bon travail ! Déjà desserré ? Terminons le travail.", "*plante ses bottes comme sur une pente de montagne; frappe une section d'armure déjà fragilisée.*", "Une enclume ne se plaint pas d'un bon coup de marteau. Votre forgeron a visiblement économisé au mauvais endroit.", "*repousse une mèche de barbe égarée; tapote une jointure découverte, puis frappe de nouveau.*" },
        SHIELD_SLAM = { "Par la barbe de ma grand-mère, voilà du bon travail ! Un bouclier ferme aussi les portes. Souvent à hauteur de visage.", "*repousse une mèche de barbe égarée; arrache le bouclier de sa garde et projette le bord en avant.*", "Les genoux qui tremblent ? Pas dans cette famille. Qui a prétendu que la défense devait être polie ?", "*frappe sa cuirasse du pommeau de son arme; bondit d'un pas et laisse parler son bouclier.*" },
        CONCUSSION_BLOW = { "Par la barbe de ma grand-mère, voilà du bon travail ! Je vais essayer de vous déconcentrer.", "*frappe sa cuirasse du pommeau de son arme; tente de porter un coup lourd entre deux mouvements adverses.*", "La pierre se souvient de ceux qui ont cédé devant elle. Je vais essayer d’offrir un instant de silence à tout le monde.", "*frappe du doigt le bord bosselé de son bouclier; raccourcit sa prise et tente de frapper avec une force surprenante.*" },
        VICTORY_RUSH = { "Ces bottes ne connaissent qu'une direction : devant. Un de moins. Les autres tiennent encore debout.", "*frappe du doigt le bord bosselé de son bouclier; profite de son regain d'énergie pour repartir à l'assaut.*", "Nous en parlerons autour d'une chope. Peut-être. Nous fêterons cela plus tard. Quelque chose bouge encore.", "*crache résolument dans ses gants; se frappe une fois la poitrine et avance aussitôt.*" },
        BATTLE_STANCE = { "Mon grand-père appelait ça le bon sens des montagnes. Deux pieds bien placés séparent le courage de la sottise.", "*crache résolument dans ses gants; plante les pieds à largeur d'épaules et fait rouler sa lame.*", "Une enclume ne se plaint pas d'un bon coup de marteau. Je reste prêt. Au reste du monde de décider.", "*enfonce le casque au-dessus de ses sourcils broussailleux; répartit son poids entre le bras de bouclier et la main armée.*" },
        DEFENSIVE_STANCE = { "La montagne ne demande pas la force du vent. Pour atteindre les miens, il faudra convaincre mon bouclier.", "*enfonce le casque au-dessus de ses sourcils broussailleux; élargit ses appuis et lève le bouclier devant ses alliés.*", "Les genoux qui tremblent ? Pas dans cette famille. Ce n'est pas le cri le plus fort qui gagnera aujourd'hui.", "*plante ses bottes comme sur une pente de montagne; abaisse son centre de gravité et devient un mur derrière sa garde.*" },
        BERSERKER_STANCE = { "Ma colère monte de loin, à hauteur de tonneau. Qui a dit que la colère rend aveugle n'a jamais vraiment regardé.", "*plante ses bottes comme sur une pente de montagne; inspire profondément et prend une posture féroce.*", "La pierre se souvient de ceux qui ont cédé devant elle. Le monde est soudain très simple : en avant.", "*repousse une mèche de barbe égarée; relâche les épaules, abaisse son arme, puis la relève vivement.*" },
        PIERCING_HOWL = { "Qui n'entend pas ça depuis la taverne n'a plus d'espoir ! Si vous m'entendez, c'est déjà trop tard.", "*repousse une mèche de barbe égarée; pousse un hurlement qui perce tout le vacarme alentour.*", "Nous en parlerons autour d'une chope. Peut-être. Non, ce n'était pas une meute de loups. Seulement moi.", "*frappe sa cuirasse du pommeau de son arme; renverse la tête et laisse monter un long cri rauque.*" },
        SPEARING_STRIKE = { "Par la barbe de ma grand-mère, voilà du bon travail ! La brèche est étroite. Ma pointe ne l'est pas.", "*frappe sa cuirasse du pommeau de son arme; avance droit devant, l'arme tendue.*", "Une enclume ne se plaint pas d'un bon coup de marteau. L'armure est solide. Les angles sont plus forts.", "*frappe du doigt le bord bosselé de son bouclier; tourne le poignet vers la faille et pousse la pointe.*" },
        TACTICAL_MASTERY = { "Mon grand-père appelait ça le bon sens des montagnes. Entre le courage et la sottise, il y a de bons appuis.", "*frappe du doigt le bord bosselé de son bouclier; ajuste sa position d'un rien et garde le champ de bataille en vue.*", "Les genoux qui tremblent ? Pas dans cette famille. Un champ de bataille ne se joue pas aux dés. Il se lit.", "*crache résolument dans ses gants; observe les chemins, les ennemis et les retraites sans abaisser son arme.*" },
    },
    NIGHTELF = {
        HEROIC_STRIKE = { "Même en bataille, il existe un silence entre deux feuilles. Vous savez pourquoi cette arme est lourde ? Elle discute rarement.", "*effleure une ancienne gravure en forme de feuille; porte son poids vers l'avant et abat son arme avec vigueur.*", "La nuit se souvient plus longtemps que cette querelle. Certains arguments n'ont pas besoin de seconde phrase.", "*expire sans un bruit; engage l'épaule et laisse l'acier finir la démonstration.*" },
        CHARGE = { "Le chemin apparaît quand on écoute le vent. Si le chemin est fermé, je prends la ligne droite.", "*expire sans un bruit; baisse l'épaule et s'élance dans un nuage de poussière.*", "Je combats pour l'équilibre, jamais contre lui. J'arrive ! Ce n'est pas une menace, c'est un itinéraire !", "*adapte ses appuis aux irrégularités du sol; traverse une brèche dans un fracas d'armure.*" },
        REND = { "Même en bataille, il existe un silence entre deux feuilles. Les coutures des armures cachent de petits secrets. Je suis curieux.", "*adapte ses appuis aux irrégularités du sol; fait glisser sa lame dans une ouverture de la garde.*", "Même un arbre qui tombe choisit son chemin. Un tailleur serait scandalisé. Moi, je suis ravi.", "*incline la tête comme si une forêt lointaine répondait; retire sa lame et cherche une nouvelle faille.*" },
        HAMSTRING = { "Même en bataille, il existe un silence entre deux feuilles. Vous enfuir ? Voilà un plan bien fragile.", "*incline la tête comme si une forêt lointaine répondait; se baisse vivement sous la garde adverse.*", "Certains combats ne cessent qu'au retour du silence. Je n'aime pas courir deux fois. Une fois suffit.", "*glisse silencieusement d'un pas de côté; fauche bas et reprend immédiatement sa garde.*" },
        THUNDER_CLAP = { "Même en bataille, il existe un silence entre deux feuilles. Quand le sol tremble, plus besoin de tambour.", "*glisse silencieusement d'un pas de côté; frappe si fort du pied que la poussière bondit.*", "La nuit se souvient plus longtemps que cette querelle. Vous entendez ? Même la terre proteste.", "*oriente sa lame après un bref regard vers le ciel; écarte les bras et laisse une onde sourde courir parmi les rangs.*" },
        CLEAVE = { "La patience est la plus longue arme que je porte. Si vous venez côte à côte, vous partagerez les ennuis.", "*oriente sa lame après un bref regard vers le ciel; décrit un vaste arc avec son arme dans la mêlée.*", "Je combats pour l'équilibre, jamais contre lui. J'espère que vous avez gardé assez de place. Pas moi.", "*effleure une ancienne gravure en forme de feuille; pivote sur un talon et prolonge l'élan d'un second mouvement.*" },
        EXECUTE = { "Même en bataille, il existe un silence entre deux feuilles. Je vous ai laissé toutes les occasions de battre en retraite.", "*effleure une ancienne gravure en forme de feuille; attend un battement de cœur, puis abat un coup décisif.*", "Même un arbre qui tombe choisit son chemin. Les négociations sont terminées.", "*expire sans un bruit; resserre sa prise et referme la dernière ouverture.*" },
        SUNDER_ARMOR = { "Même en bataille, il existe un silence entre deux feuilles. Belle cuirasse. Dommage pour les rivets.", "*expire sans un bruit; place le tranchant contre une jointure d'armure.*", "Certains combats ne cessent qu'au retour du silence. Un acier coûteux ne remplace pas une bonne garde.", "*adapte ses appuis aux irrégularités du sol; trace du fil de la lame une ligne entre deux plaques.*" },
        SHIELD_BLOCK = { "Le chêne ne bouge pas parce que le vent devient impoli.", "*adapte ses appuis aux irrégularités du sol; tourne le bord du bouclier pour recevoir le coup.*", "La nuit se souvient plus longtemps que cette querelle. Un bon bouclier écoute avant de répondre.", "*incline la tête comme si une forêt lointaine répondait; plante ses bottes au sol sans céder un pouce.*" },
        SHIELD_BASH = { "Même en bataille, il existe un silence entre deux feuilles. Chut. Voyons si je peux interrompre votre sort.", "*incline la tête comme si une forêt lointaine répondait; pousse son bouclier en avant entre deux syllabes.*", "Je combats pour l'équilibre, jamais contre lui. Ma réponse à la magie possède une poignée de bois.", "*glisse silencieusement d'un pas de côté; avance d'un pas et tente de percuter sans prévenir.*" },
        TAUNT = { "Même en bataille, il existe un silence entre deux feuilles. Par ici ! Les ennuis portent mon nom aujourd'hui.", "*glisse silencieusement d'un pas de côté; frappe trois fois la poignée de son arme contre son bouclier.*", "Même un arbre qui tombe choisit son chemin. Les autres sont occupés. Pas moi.", "*oriente sa lame après un bref regard vers le ciel; sort de la ligne et invite les ennemis à approcher.*" },
        BATTLE_SHOUT = { "Mon appel traverse l'obscurité des forêts. Têtes hautes, rangs serrés ! Personne ne tombe seul !", "*oriente sa lame après un bref regard vers le ciel; bat la mesure avec la poignée contre le bouclier.*", "Certains combats ne cessent qu'au retour du silence. Vous avez des jambes pour tenir et du cœur pour résister. Servez-vous-en !", "*effleure une ancienne gravure en forme de feuille; se dresse devant ses alliés et lève la lame.*" },
        DEMORALIZING_SHOUT = { "Mon appel traverse l'obscurité des forêts. Les premiers tremblent déjà. Les derniers suivront !", "*effleure une ancienne gravure en forme de feuille; pousse un cri profond et rugueux du fond de la poitrine.*", "La nuit se souvient plus longtemps que cette querelle. Regardez autour de vous. Pour qui vous battez-vous encore ?", "*expire sans un bruit; désigne de sa lame les lignes ennemies vacillantes.*" },
        REVENGE = { "Même en bataille, il existe un silence entre deux feuilles. Merci pour l'occasion. Je vous la rends aussitôt.", "*expire sans un bruit; dévie une arme et frappe dans la brèche.*", "Je combats pour l'équilibre, jamais contre lui. J'oublie les visages. Jamais les coups.", "*adapte ses appuis aux irrégularités du sol; passe directement de la parade à la riposte.*" },
        OVERPOWER = { "Même en bataille, il existe un silence entre deux feuilles. Voilà une faille. Comme c'est généreux de votre part.", "*adapte ses appuis aux irrégularités du sol; esquive le coup manqué et saisit l'angle ouvert.*", "Même un arbre qui tombe choisit son chemin. Manquez-moi une fois, vous m'invitez à entrer.", "*incline la tête comme si une forêt lointaine répondait; transforme un faux pas adverse en riposte éclair.*" },
        MORTAL_STRIKE = { "Même en bataille, il existe un silence entre deux feuilles. Je ne garde rien pour une seconde tentative.", "*incline la tête comme si une forêt lointaine répondait; saisit son arme à deux mains et engage tout son poids.*", "Certains combats ne cessent qu'au retour du silence. Certains duels se règlent en paroles. Pas celui-ci.", "*glisse silencieusement d'un pas de côté; avance et conduit l'acier avec une précision implacable.*" },
        WHIRLWIND = { "Le vent d'automne ne demande pas la permission aux feuilles.", "*glisse silencieusement d'un pas de côté; tourne dans la mêlée, l'arme tendue à bout de bras.*", "La nuit se souvient plus longtemps que cette querelle. J'aime partager. Aujourd'hui, c'est de l'acier.", "*oriente sa lame après un bref regard vers le ciel; fait chanter la lame dans un large mouvement circulaire.*" },
        BLOODTHIRST = { "La nature connaît la colère et les limites qu'elle doit garder. Le pouls s'emballe. La main reste sûre.", "*oriente sa lame après un bref regard vers le ciel; expire brusquement et poursuit son assaut sans relâche.*", "Je combats pour l'équilibre, jamais contre lui. La colère ne rend pas mes coups imprécis.", "*effleure une ancienne gravure en forme de feuille; se rue en avant, les yeux sauvages, la prise parfaitement mesurée.*" },
        INTERCEPT = { "Le chemin apparaît quand on écoute le vent. Une avance n'est qu'un temps emprunté.", "*effleure une ancienne gravure en forme de feuille; jaillit de la mêlée et coupe toute retraite.*", "Même un arbre qui tombe choisit son chemin. Vous courez ? Parfait, j'avais besoin d'exercice.", "*expire sans un bruit; bondit de sa position et atterrit sur le chemin de la fuite.*" },
        PUMMEL = { "Même en bataille, il existe un silence entre deux feuilles. Trop de paroles. Pas assez de garde.", "*expire sans un bruit; rompt le geste d'incantation d'un coup sec et précis.*", "Certains combats ne cessent qu'au retour du silence. Vous vouliez ajouter quelque chose ? Non ? Bien.", "*adapte ses appuis aux irrégularités du sol; désorganise le mouvement du bras d'un petit coup.*" },
        SWEEPING_STRIKES = { "La patience est la plus longue arme que je porte. Pourquoi faire la moitié du travail quand toute une bataille nous attend ?", "*adapte ses appuis aux irrégularités du sol; prolonge le premier coup en un second arc fluide.*", "La nuit se souvient plus longtemps que cette querelle. Plus d'ennemis ? Moins de déplacements.", "*incline la tête comme si une forêt lointaine répondait; poursuit le mouvement de la lame à travers la mêlée.*" },
