        SLAM = { "Même en bataille, il existe un silence entre deux feuilles. Ce n'est pas un marteau. Vous ne sentirez guère la différence.", "*adapte ses appuis aux irrégularités du sol; lève son arme au-dessus de l'épaule et l'abat de tout son poids.*", "La nuit se souvient plus longtemps que cette querelle. Un coup net vaut cinq coups timides.", "*incline la tête comme si une forêt lointaine répondait; suspend un instant le mouvement, puis frappe lourdement.*" },
        DEVASTATE = { "Même en bataille, il existe un silence entre deux feuilles. Déjà desserré ? Terminons le travail.", "*incline la tête comme si une forêt lointaine répondait; frappe une section d'armure déjà fragilisée.*", "Je combats pour l'équilibre, jamais contre lui. Votre forgeron a visiblement économisé au mauvais endroit.", "*glisse silencieusement d'un pas de côté; tapote une jointure découverte, puis frappe de nouveau.*" },
        SHIELD_SLAM = { "Même en bataille, il existe un silence entre deux feuilles. Un bouclier ferme aussi les portes. Souvent à hauteur de visage.", "*glisse silencieusement d'un pas de côté; arrache le bouclier de sa garde et projette le bord en avant.*", "Même un arbre qui tombe choisit son chemin. Qui a prétendu que la défense devait être polie ?", "*oriente sa lame après un bref regard vers le ciel; bondit d'un pas et laisse parler son bouclier.*" },
        CONCUSSION_BLOW = { "Même en bataille, il existe un silence entre deux feuilles. Je vais essayer de vous déconcentrer.", "*oriente sa lame après un bref regard vers le ciel; tente de porter un coup lourd entre deux mouvements adverses.*", "Certains combats ne cessent qu'au retour du silence. Je vais essayer d’offrir un instant de silence à tout le monde.", "*effleure une ancienne gravure en forme de feuille; raccourcit sa prise et tente de frapper avec une force surprenante.*" },
        VICTORY_RUSH = { "Le chemin apparaît quand on écoute le vent. Un de moins. Les autres tiennent encore debout.", "*effleure une ancienne gravure en forme de feuille; profite de son regain d'énergie pour repartir à l'assaut.*", "La nuit se souvient plus longtemps que cette querelle. Nous fêterons cela plus tard. Quelque chose bouge encore.", "*expire sans un bruit; se frappe une fois la poitrine et avance aussitôt.*" },
        BATTLE_STANCE = { "La patience est la plus longue arme que je porte. Deux pieds bien placés séparent le courage de la sottise.", "*expire sans un bruit; plante les pieds à largeur d'épaules et fait rouler sa lame.*", "Je combats pour l'équilibre, jamais contre lui. Je reste prêt. Au reste du monde de décider.", "*adapte ses appuis aux irrégularités du sol; répartit son poids entre le bras de bouclier et la main armée.*" },
        DEFENSIVE_STANCE = { "Les racines anciennes ne s'arrachent pas aisément. Pour atteindre les miens, il faudra convaincre mon bouclier.", "*adapte ses appuis aux irrégularités du sol; élargit ses appuis et lève le bouclier devant ses alliés.*", "Même un arbre qui tombe choisit son chemin. Ce n'est pas le cri le plus fort qui gagnera aujourd'hui.", "*incline la tête comme si une forêt lointaine répondait; abaisse son centre de gravité et devient un mur derrière sa garde.*" },
        BERSERKER_STANCE = { "La nature connaît la colère et les limites qu'elle doit garder. Qui a dit que la colère rend aveugle n'a jamais vraiment regardé.", "*incline la tête comme si une forêt lointaine répondait; inspire profondément et prend une posture féroce.*", "Certains combats ne cessent qu'au retour du silence. Le monde est soudain très simple : en avant.", "*glisse silencieusement d'un pas de côté; relâche les épaules, abaisse son arme, puis la relève vivement.*" },
        PIERCING_HOWL = { "Écoutez la nuit. Cette fois, elle emprunte ma voix.", "*glisse silencieusement d'un pas de côté; pousse un hurlement qui perce tout le vacarme alentour.*", "La nuit se souvient plus longtemps que cette querelle. Non, ce n'était pas une meute de loups. Seulement moi.", "*oriente sa lame après un bref regard vers le ciel; renverse la tête et laisse monter un long cri rauque.*" },
        SPEARING_STRIKE = { "Même en bataille, il existe un silence entre deux feuilles. La brèche est étroite. Ma pointe ne l'est pas.", "*oriente sa lame après un bref regard vers le ciel; avance droit devant, l'arme tendue.*", "Je combats pour l'équilibre, jamais contre lui. L'armure est solide. Les angles sont plus forts.", "*effleure une ancienne gravure en forme de feuille; tourne le poignet vers la faille et pousse la pointe.*" },
        TACTICAL_MASTERY = { "Parfois, c'est l'arbre qui plie le premier qui gagne.", "*effleure une ancienne gravure en forme de feuille; ajuste sa position d'un rien et garde le champ de bataille en vue.*", "Même un arbre qui tombe choisit son chemin. Un champ de bataille ne se joue pas aux dés. Il se lit.", "*expire sans un bruit; observe les chemins, les ennemis et les retraites sans abaisser son arme.*" },
    },
    DRAENEI = {
        HEROIC_STRIKE = { "Que cela protège les miens plutôt que d'écraser les faibles. Vous savez pourquoi cette arme est lourde ? Elle discute rarement.", "*touche brièvement un souvenir fixé à son armure; porte son poids vers l'avant et abat son arme avec vigueur.*", "Pour chaque vie derrière moi, je tiendrai un battement de plus. Certains arguments n'ont pas besoin de seconde phrase.", "*abaisse les cornes et répartit son poids; engage l'épaule et laisse l'acier finir la démonstration.*" },
        CHARGE = { "Chaque pas est une promesse à ceux qui sont restés derrière. Si le chemin est fermé, je prends la ligne droite.", "*abaisse les cornes et répartit son poids; baisse l'épaule et s'élance dans un nuage de poussière.*", "La Lumière montre le chemin. C'est à moi d'agir. J'arrive ! Ce n'est pas une menace, c'est un itinéraire !", "*place son bouclier devant ses alliés; traverse une brèche dans un fracas d'armure.*" },
        REND = { "Que cela protège les miens plutôt que d'écraser les faibles. Les coutures des armures cachent de petits secrets. Je suis curieux.", "*place son bouclier devant ses alliés; fait glisser sa lame dans une ouverture de la garde.*", "Le souvenir des mondes perdus pèse sur ma volonté. Un tailleur serait scandalisé. Moi, je suis ravi.", "*inspire profondément et retrouve son calme; retire sa lame et cherche une nouvelle faille.*" },
        HAMSTRING = { "Que cela protège les miens plutôt que d'écraser les faibles. Vous enfuir ? Voilà un plan bien fragile.", "*inspire profondément et retrouve son calme; se baisse vivement sous la garde adverse.*", "Je ne cherche pas la gloire, seulement le retour de tous. Je n'aime pas courir deux fois. Une fois suffit.", "*vérifie ses appuis de sabot sur le sol; fauche bas et reprend immédiatement sa garde.*" },
        THUNDER_CLAP = { "Que cela protège les miens plutôt que d'écraser les faibles. Quand le sol tremble, plus besoin de tambour.", "*vérifie ses appuis de sabot sur le sol; frappe si fort du pied que la poussière bondit.*", "Pour chaque vie derrière moi, je tiendrai un battement de plus. Vous entendez ? Même la terre proteste.", "*pose la main sur un ancien emblème familial; écarte les bras et laisse une onde sourde courir parmi les rangs.*" },
        CLEAVE = { "Un esprit clair résiste aux plus terribles tempêtes. Si vous venez côte à côte, vous partagerez les ennuis.", "*pose la main sur un ancien emblème familial; décrit un vaste arc avec son arme dans la mêlée.*", "La Lumière montre le chemin. C'est à moi d'agir. J'espère que vous avez gardé assez de place. Pas moi.", "*touche brièvement un souvenir fixé à son armure; pivote sur un talon et prolonge l'élan d'un second mouvement.*" },
        EXECUTE = { "Que cela protège les miens plutôt que d'écraser les faibles. Je vous ai laissé toutes les occasions de battre en retraite.", "*touche brièvement un souvenir fixé à son armure; attend un battement de cœur, puis abat un coup décisif.*", "Le souvenir des mondes perdus pèse sur ma volonté. Les négociations sont terminées.", "*abaisse les cornes et répartit son poids; resserre sa prise et referme la dernière ouverture.*" },
        SUNDER_ARMOR = { "Que cela protège les miens plutôt que d'écraser les faibles. Belle cuirasse. Dommage pour les rivets.", "*abaisse les cornes et répartit son poids; place le tranchant contre une jointure d'armure.*", "Je ne cherche pas la gloire, seulement le retour de tous. Un acier coûteux ne remplace pas une bonne garde.", "*place son bouclier devant ses alliés; trace du fil de la lame une ligne entre deux plaques.*" },
        SHIELD_BLOCK = { "La ténacité commence là où les autres cherchent refuge. Il faudra frapper à la porte. Mon bouclier reste fermé.", "*place son bouclier devant ses alliés; tourne le bord du bouclier pour recevoir le coup.*", "Pour chaque vie derrière moi, je tiendrai un battement de plus. Un bon bouclier écoute avant de répondre.", "*inspire profondément et retrouve son calme; plante ses bottes au sol sans céder un pouce.*" },
        SHIELD_BASH = { "Que cela protège les miens plutôt que d'écraser les faibles. Chut. Voyons si je peux interrompre votre sort.", "*inspire profondément et retrouve son calme; pousse son bouclier en avant entre deux syllabes.*", "La Lumière montre le chemin. C'est à moi d'agir. Ma réponse à la magie possède une poignée de bois.", "*vérifie ses appuis de sabot sur le sol; avance d'un pas et tente de percuter sans prévenir.*" },
        TAUNT = { "Les plus faibles ne sont pas des cibles. Essayez-moi.", "*vérifie ses appuis de sabot sur le sol; frappe trois fois la poignée de son arme contre son bouclier.*", "Le souvenir des mondes perdus pèse sur ma volonté. Les autres sont occupés. Pas moi.", "*pose la main sur un ancien emblème familial; sort de la ligne et invite les ennemis à approcher.*" },
        BATTLE_SHOUT = { "Vous n'êtes pas seuls. Pas un seul d'entre vous !", "*pose la main sur un ancien emblème familial; bat la mesure avec la poignée contre le bouclier.*", "Je ne cherche pas la gloire, seulement le retour de tous. Vous avez des jambes pour tenir et du cœur pour résister. Servez-vous-en !", "*touche brièvement un souvenir fixé à son armure; se dresse devant ses alliés et lève la lame.*" },
        DEMORALIZING_SHOUT = { "Que ma voix porte l'espoir, pas seulement la peur. Les premiers tremblent déjà. Les derniers suivront !", "*touche brièvement un souvenir fixé à son armure; pousse un cri profond et rugueux du fond de la poitrine.*", "Pour chaque vie derrière moi, je tiendrai un battement de plus. Regardez autour de vous. Pour qui vous battez-vous encore ?", "*abaisse les cornes et répartit son poids; désigne de sa lame les lignes ennemies vacillantes.*" },
        REVENGE = { "Que cela protège les miens plutôt que d'écraser les faibles. Merci pour l'occasion. Je vous la rends aussitôt.", "*abaisse les cornes et répartit son poids; dévie une arme et frappe dans la brèche.*", "La Lumière montre le chemin. C'est à moi d'agir. J'oublie les visages. Jamais les coups.", "*place son bouclier devant ses alliés; passe directement de la parade à la riposte.*" },
        OVERPOWER = { "Que cela protège les miens plutôt que d'écraser les faibles. Voilà une faille. Comme c'est généreux de votre part.", "*place son bouclier devant ses alliés; esquive le coup manqué et saisit l'angle ouvert.*", "Le souvenir des mondes perdus pèse sur ma volonté. Manquez-moi une fois, vous m'invitez à entrer.", "*inspire profondément et retrouve son calme; transforme un faux pas adverse en riposte éclair.*" },
        MORTAL_STRIKE = { "Que cela protège les miens plutôt que d'écraser les faibles. Je ne garde rien pour une seconde tentative.", "*inspire profondément et retrouve son calme; saisit son arme à deux mains et engage tout son poids.*", "Je ne cherche pas la gloire, seulement le retour de tous. Certains duels se règlent en paroles. Pas celui-ci.", "*vérifie ses appuis de sabot sur le sol; avance et conduit l'acier avec une précision implacable.*" },
        WHIRLWIND = { "Un esprit clair résiste aux plus terribles tempêtes. Mettez-vous donc en cercle. Cela m'arrange.", "*vérifie ses appuis de sabot sur le sol; tourne dans la mêlée, l'arme tendue à bout de bras.*", "Pour chaque vie derrière moi, je tiendrai un battement de plus. J'aime partager. Aujourd'hui, c'est de l'acier.", "*pose la main sur un ancien emblème familial; fait chanter la lame dans un large mouvement circulaire.*" },
        BLOODTHIRST = { "Même maintenant, la fureur ne gouvernera pas ma volonté. Le pouls s'emballe. La main reste sûre.", "*pose la main sur un ancien emblème familial; expire brusquement et poursuit son assaut sans relâche.*", "La Lumière montre le chemin. C'est à moi d'agir. La colère ne rend pas mes coups imprécis.", "*touche brièvement un souvenir fixé à son armure; se rue en avant, les yeux sauvages, la prise parfaitement mesurée.*" },
        INTERCEPT = { "Chaque pas est une promesse à ceux qui sont restés derrière. Une avance n'est qu'un temps emprunté.", "*touche brièvement un souvenir fixé à son armure; jaillit de la mêlée et coupe toute retraite.*", "Le souvenir des mondes perdus pèse sur ma volonté. Vous courez ? Parfait, j'avais besoin d'exercice.", "*abaisse les cornes et répartit son poids; bondit de sa position et atterrit sur le chemin de la fuite.*" },
        PUMMEL = { "Que cela protège les miens plutôt que d'écraser les faibles. Trop de paroles. Pas assez de garde.", "*abaisse les cornes et répartit son poids; rompt le geste d'incantation d'un coup sec et précis.*", "Je ne cherche pas la gloire, seulement le retour de tous. Vous vouliez ajouter quelque chose ? Non ? Bien.", "*place son bouclier devant ses alliés; désorganise le mouvement du bras d'un petit coup.*" },
        SWEEPING_STRIKES = { "Un esprit clair résiste aux plus terribles tempêtes. Pourquoi faire la moitié du travail quand toute une bataille nous attend ?", "*place son bouclier devant ses alliés; prolonge le premier coup en un second arc fluide.*", "Pour chaque vie derrière moi, je tiendrai un battement de plus. Plus d'ennemis ? Moins de déplacements.", "*inspire profondément et retrouve son calme; poursuit le mouvement de la lame à travers la mêlée.*" },
        DEATH_WISH = { "Même maintenant, la fureur ne gouvernera pas ma volonté. La raison a donné son avis. Je ne suis pas d'accord.", "*inspire profondément et retrouve son calme; relâche un instant sa prise et choisit l'attaque.*", "La Lumière montre le chemin. C'est à moi d'agir. Je connais le risque. Eux, peut-être pas.", "*vérifie ses appuis de sabot sur le sol; jette un dernier regard à sa garde avant de bondir.*" },
        RECKLESSNESS = { "Même maintenant, la fureur ne gouvernera pas ma volonté. La prudence, c'était hier. Aujourd'hui, on agit.", "*vérifie ses appuis de sabot sur le sol; rejette l'hésitation sans lâcher son arme.*", "Le souvenir des mondes perdus pèse sur ma volonté. Vous pourrez me faire la morale demain. S'il y a un demain.", "*pose la main sur un ancien emblème familial; engage tout son corps dans une suite de coups furieux.*" },
        LAST_STAND = { "J'ai vu tomber des mondes. Cette position tiendra.", "*pose la main sur un ancien emblème familial; se relève péniblement et lève de nouveau le bouclier.*", "Je ne cherche pas la gloire, seulement le retour de tous. Je tiens encore debout. Voilà ma réponse.", "*touche brièvement un souvenir fixé à son armure; replace ses jambes tremblantes dans la brèche.*" },
        SHIELD_WALL = { "Aucun réfugié derrière moi n'aura à fuir de nouveau aujourd'hui.", "*touche brièvement un souvenir fixé à son armure; ramène le bouclier contre soi et serre la ligne alliée.*", "Pour chaque vie derrière moi, je tiendrai un battement de plus. Qui veut passer devra avoir de la patience.", "*abaisse les cornes et répartit son poids; ferme la dernière brèche entre le bouclier et l'armure.*" },
        RETALIATION = { "Que cela protège les miens plutôt que d'écraser les faibles. Qui frappe doit apprécier l'écho.", "*abaisse les cornes et répartit son poids; entrouvre la garde et répond à chaque coup par l'acier.*", "La Lumière montre le chemin. C'est à moi d'agir. Venez donc. J'ai un instant pour chacun.", "*place son bouclier devant ses alliés; ancre les pieds et attend les coups impatients.*" },
        MOCKING_BLOW = { "Que cela protège les miens plutôt que d'écraser les faibles. Vous êtes dangereux ou simplement bruyant ?", "*place son bouclier devant ses alliés; abaisse trop ostensiblement la pointe et attire l'ennemi.*", "Le souvenir des mondes perdus pèse sur ma volonté. Pardon. Je vous ai pris pour un mannequin d'entraînement.", "*inspire profondément et retrouve son calme; porte une petite taille insolente et sourit au-dessus du bouclier.*" },
        BERSERKER_RAGE = { "Même maintenant, la fureur ne gouvernera pas ma volonté. La peur ? Pas de place pour elle aujourd'hui.", "*inspire profondément et retrouve son calme; roule les épaules comme pour se débarrasser d'un poids invisible.*", "Je ne cherche pas la gloire, seulement le retour de tous. La peur peut attendre dehors. Ma fureur entre.", "*vérifie ses appuis de sabot sur le sol; expire brutalement et fixe le combat sans ciller.*" },
        BLOODRAGE = { "Même maintenant, la fureur ne gouvernera pas ma volonté. La douleur est un message. Je répondrai plus tard.", "*vérifie ses appuis de sabot sur le sol; frappe son torse du poing et rassemble son ardeur.*", "Pour chaque vie derrière moi, je tiendrai un battement de plus. Le cœur bat encore. Cela suffit comme explication.", "*pose la main sur un ancien emblème familial; serre les dents et raidit les épaules sous l'armure.*" },
        DISARM = { "Que cela protège les miens plutôt que d'écraser les faibles. Jolie épée. Puis-je la voir un instant ?", "*pose la main sur un ancien emblème familial; tente d'arracher l'arme adverse d'une brève torsion.*", "La Lumière montre le chemin. C'est à moi d'agir. Voyons si vous êtes aussi bavard sans arme.", "*touche brièvement un souvenir fixé à son armure; tente de saisir le bras armé et de détourner le manche hors de sa ligne.*" },
        INTIMIDATING_SHOUT = { "Que ma voix porte l'espoir, pas seulement la peur. Fuyez tant que vous connaissez encore la route !", "*touche brièvement un souvenir fixé à son armure; lance un rugissement féroce au-dessus des têtes ennemies.*", "Le souvenir des mondes perdus pèse sur ma volonté. C'était mon avertissement poli. Le prochain sera d'acier.", "*abaisse les cornes et répartit son poids; frappe le bouclier et découvre les dents.*" },
