    ORC = {
        HEROIC_STRIKE = { "L'honneur se gagne en actes, pas en discours. Vous savez pourquoi cette arme est lourde ? Elle discute rarement.", "*frappe du poing un ancien symbole de clan; porte son poids vers l'avant et abat son arme avec vigueur.*", "Je ne laisserai pas les autres tenir seuls devant moi. Certains arguments n'ont pas besoin de seconde phrase.", "*découvre les défenses dans un sourire décidé; engage l'épaule et laisse l'acier finir la démonstration.*" },
        CHARGE = { "Que ceux qui me voient avancer racontent comment combat un clan !", "*découvre les défenses dans un sourire décidé; baisse l'épaule et s'élance dans un nuage de poussière.*", "Ma hache connaît la vérité sur les fanfarons. J'arrive ! Ce n'est pas une menace, c'est un itinéraire !", "*ancre les pieds dans la terre retournée; traverse une brèche dans un fracas d'armure.*" },
        REND = { "L'honneur se gagne en actes, pas en discours. Les coutures des armures cachent de petits secrets. Je suis curieux.", "*ancre les pieds dans la terre retournée; fait glisser sa lame dans une ouverture de la garde.*", "Un guerrier sans responsabilité n'est qu'un sot bruyant. Un tailleur serait scandalisé. Moi, je suis ravi.", "*passe le pouce sur une entaille du manche de son arme; retire sa lame et cherche une nouvelle faille.*" },
        HAMSTRING = { "L'honneur se gagne en actes, pas en discours. Vous enfuir ? Voilà un plan bien fragile.", "*passe le pouce sur une entaille du manche de son arme; se baisse vivement sous la garde adverse.*", "Que les ancêtres voient qui je suis dans ma façon de tenir. Je n'aime pas courir deux fois. Une fois suffit.", "*laisse échapper un souffle rauque; fauche bas et reprend immédiatement sa garde.*" },
        THUNDER_CLAP = { "L'honneur se gagne en actes, pas en discours. Quand le sol tremble, plus besoin de tambour.", "*laisse échapper un souffle rauque; frappe si fort du pied que la poussière bondit.*", "Je ne laisserai pas les autres tenir seuls devant moi. Vous entendez ? Même la terre proteste.", "*resserre le cuir enroulé autour de la poignée; écarte les bras et laisse une onde sourde courir parmi les rangs.*" },
        CLEAVE = { "Les ancêtres ne louent pas une victoire achetée par la sottise. Si vous venez côte à côte, vous partagerez les ennuis.", "*resserre le cuir enroulé autour de la poignée; décrit un vaste arc avec son arme dans la mêlée.*", "Ma hache connaît la vérité sur les fanfarons. J'espère que vous avez gardé assez de place. Pas moi.", "*frappe du poing un ancien symbole de clan; pivote sur un talon et prolonge l'élan d'un second mouvement.*" },
        EXECUTE = { "L'honneur se gagne en actes, pas en discours. Je vous ai laissé toutes les occasions de battre en retraite.", "*frappe du poing un ancien symbole de clan; attend un battement de cœur, puis abat un coup décisif.*", "Un guerrier sans responsabilité n'est qu'un sot bruyant. Les négociations sont terminées.", "*découvre les défenses dans un sourire décidé; resserre sa prise et referme la dernière ouverture.*" },
        SUNDER_ARMOR = { "L'honneur se gagne en actes, pas en discours. Belle cuirasse. Dommage pour les rivets.", "*découvre les défenses dans un sourire décidé; place le tranchant contre une jointure d'armure.*", "Que les ancêtres voient qui je suis dans ma façon de tenir. Un acier coûteux ne remplace pas une bonne garde.", "*ancre les pieds dans la terre retournée; trace du fil de la lame une ligne entre deux plaques.*" },
        SHIELD_BLOCK = { "Mon épaule ne cédera pas tant que quelqu'un respire derrière moi.", "*ancre les pieds dans la terre retournée; tourne le bord du bouclier pour recevoir le coup.*", "Je ne laisserai pas les autres tenir seuls devant moi. Un bon bouclier écoute avant de répondre.", "*passe le pouce sur une entaille du manche de son arme; plante ses bottes au sol sans céder un pouce.*" },
        SHIELD_BASH = { "L'honneur se gagne en actes, pas en discours. Chut. Voyons si je peux interrompre votre sort.", "*passe le pouce sur une entaille du manche de son arme; pousse son bouclier en avant entre deux syllabes.*", "Ma hache connaît la vérité sur les fanfarons. Ma réponse à la magie possède une poignée de bois.", "*laisse échapper un souffle rauque; avance d'un pas et tente de percuter sans prévenir.*" },
        TAUNT = { "Regardez-moi dans les yeux. L'honneur ignore les embuscades.", "*laisse échapper un souffle rauque; frappe trois fois la poignée de son arme contre son bouclier.*", "Un guerrier sans responsabilité n'est qu'un sot bruyant. Les autres sont occupés. Pas moi.", "*resserre le cuir enroulé autour de la poignée; sort de la ligne et invite les ennemis à approcher.*" },
        BATTLE_SHOUT = { "POUR LE CLAN ! Pour ceux qui se tiennent à nos côtés !", "*resserre le cuir enroulé autour de la poignée; bat la mesure avec la poignée contre le bouclier.*", "Que les ancêtres voient qui je suis dans ma façon de tenir. Vous avez des jambes pour tenir et du cœur pour résister. Servez-vous-en !", "*frappe du poing un ancien symbole de clan; se dresse devant ses alliés et lève la lame.*" },
        DEMORALIZING_SHOUT = { "Que chaque guerrier du clan entende ma voix ! Les premiers tremblent déjà. Les derniers suivront !", "*frappe du poing un ancien symbole de clan; pousse un cri profond et rugueux du fond de la poitrine.*", "Je ne laisserai pas les autres tenir seuls devant moi. Regardez autour de vous. Pour qui vous battez-vous encore ?", "*découvre les défenses dans un sourire décidé; désigne de sa lame les lignes ennemies vacillantes.*" },
        REVENGE = { "L'honneur se gagne en actes, pas en discours. Merci pour l'occasion. Je vous la rends aussitôt.", "*découvre les défenses dans un sourire décidé; dévie une arme et frappe dans la brèche.*", "Ma hache connaît la vérité sur les fanfarons. J'oublie les visages. Jamais les coups.", "*ancre les pieds dans la terre retournée; passe directement de la parade à la riposte.*" },
        OVERPOWER = { "L'honneur se gagne en actes, pas en discours. Voilà une faille. Comme c'est généreux de votre part.", "*ancre les pieds dans la terre retournée; esquive le coup manqué et saisit l'angle ouvert.*", "Un guerrier sans responsabilité n'est qu'un sot bruyant. Manquez-moi une fois, vous m'invitez à entrer.", "*passe le pouce sur une entaille du manche de son arme; transforme un faux pas adverse en riposte éclair.*" },
        MORTAL_STRIKE = { "L'honneur se gagne en actes, pas en discours. Je ne garde rien pour une seconde tentative.", "*passe le pouce sur une entaille du manche de son arme; saisit son arme à deux mains et engage tout son poids.*", "Que les ancêtres voient qui je suis dans ma façon de tenir. Certains duels se règlent en paroles. Pas celui-ci.", "*laisse échapper un souffle rauque; avance et conduit l'acier avec une précision implacable.*" },
        WHIRLWIND = { "Les ancêtres ne louent pas une victoire achetée par la sottise. Mettez-vous donc en cercle. Cela m'arrange.", "*laisse échapper un souffle rauque; tourne dans la mêlée, l'arme tendue à bout de bras.*", "Je ne laisserai pas les autres tenir seuls devant moi. J'aime partager. Aujourd'hui, c'est de l'acier.", "*resserre le cuir enroulé autour de la poignée; fait chanter la lame dans un large mouvement circulaire.*" },
        BLOODTHIRST = { "Ma colère brûle. Mon intention reste claire. Le pouls s'emballe. La main reste sûre.", "*resserre le cuir enroulé autour de la poignée; expire brusquement et poursuit son assaut sans relâche.*", "Ma hache connaît la vérité sur les fanfarons. La colère ne rend pas mes coups imprécis.", "*frappe du poing un ancien symbole de clan; se rue en avant, les yeux sauvages, la prise parfaitement mesurée.*" },
        INTERCEPT = { "Le courage n'attend pas le second appel. Une avance n'est qu'un temps emprunté.", "*frappe du poing un ancien symbole de clan; jaillit de la mêlée et coupe toute retraite.*", "Un guerrier sans responsabilité n'est qu'un sot bruyant. Vous courez ? Parfait, j'avais besoin d'exercice.", "*découvre les défenses dans un sourire décidé; bondit de sa position et atterrit sur le chemin de la fuite.*" },
        PUMMEL = { "L'honneur se gagne en actes, pas en discours. Trop de paroles. Pas assez de garde.", "*découvre les défenses dans un sourire décidé; rompt le geste d'incantation d'un coup sec et précis.*", "Que les ancêtres voient qui je suis dans ma façon de tenir. Vous vouliez ajouter quelque chose ? Non ? Bien.", "*ancre les pieds dans la terre retournée; désorganise le mouvement du bras d'un petit coup.*" },
        SWEEPING_STRIKES = { "Les ancêtres ne louent pas une victoire achetée par la sottise. Pourquoi faire la moitié du travail quand toute une bataille nous attend ?", "*ancre les pieds dans la terre retournée; prolonge le premier coup en un second arc fluide.*", "Je ne laisserai pas les autres tenir seuls devant moi. Plus d'ennemis ? Moins de déplacements.", "*passe le pouce sur une entaille du manche de son arme; poursuit le mouvement de la lame à travers la mêlée.*" },
        DEATH_WISH = { "Ma colère brûle. Mon intention reste claire. La raison a donné son avis. Je ne suis pas d'accord.", "*passe le pouce sur une entaille du manche de son arme; relâche un instant sa prise et choisit l'attaque.*", "Ma hache connaît la vérité sur les fanfarons. Je connais le risque. Eux, peut-être pas.", "*laisse échapper un souffle rauque; jette un dernier regard à sa garde avant de bondir.*" },
        RECKLESSNESS = { "Ma colère brûle. Mon intention reste claire. La prudence, c'était hier. Aujourd'hui, on agit.", "*laisse échapper un souffle rauque; rejette l'hésitation sans lâcher son arme.*", "Un guerrier sans responsabilité n'est qu'un sot bruyant. Vous pourrez me faire la morale demain. S'il y a un demain.", "*resserre le cuir enroulé autour de la poignée; engage tout son corps dans une suite de coups furieux.*" },
        LAST_STAND = { "Une ligne brisée est un devoir trahi. Jusqu'ici. Pas un pas de plus.", "*resserre le cuir enroulé autour de la poignée; se relève péniblement et lève de nouveau le bouclier.*", "Que les ancêtres voient qui je suis dans ma façon de tenir. Je tiens encore debout. Voilà ma réponse.", "*frappe du poing un ancien symbole de clan; replace ses jambes tremblantes dans la brèche.*" },
        SHIELD_WALL = { "Une ligne brisée est un devoir trahi. Derrière moi ! Pas d'héroïsme solitaire !", "*frappe du poing un ancien symbole de clan; ramène le bouclier contre soi et serre la ligne alliée.*", "Je ne laisserai pas les autres tenir seuls devant moi. Qui veut passer devra avoir de la patience.", "*découvre les défenses dans un sourire décidé; ferme la dernière brèche entre le bouclier et l'armure.*" },
        RETALIATION = { "L'honneur se gagne en actes, pas en discours. Qui frappe doit apprécier l'écho.", "*découvre les défenses dans un sourire décidé; entrouvre la garde et répond à chaque coup par l'acier.*", "Ma hache connaît la vérité sur les fanfarons. Venez donc. J'ai un instant pour chacun.", "*ancre les pieds dans la terre retournée; ancre les pieds et attend les coups impatients.*" },
        MOCKING_BLOW = { "L'honneur se gagne en actes, pas en discours. Vous êtes dangereux ou simplement bruyant ?", "*ancre les pieds dans la terre retournée; abaisse trop ostensiblement la pointe et attire l'ennemi.*", "Un guerrier sans responsabilité n'est qu'un sot bruyant. Pardon. Je vous ai pris pour un mannequin d'entraînement.", "*passe le pouce sur une entaille du manche de son arme; porte une petite taille insolente et sourit au-dessus du bouclier.*" },
        BERSERKER_RAGE = { "Ma colère brûle. Mon intention reste claire. La peur ? Pas de place pour elle aujourd'hui.", "*passe le pouce sur une entaille du manche de son arme; roule les épaules comme pour se débarrasser d'un poids invisible.*", "Que les ancêtres voient qui je suis dans ma façon de tenir. La peur peut attendre dehors. Ma fureur entre.", "*laisse échapper un souffle rauque; expire brutalement et fixe le combat sans ciller.*" },
        BLOODRAGE = { "Ma colère brûle. Mon intention reste claire. La douleur est un message. Je répondrai plus tard.", "*laisse échapper un souffle rauque; frappe son torse du poing et rassemble son ardeur.*", "Je ne laisserai pas les autres tenir seuls devant moi. Le cœur bat encore. Cela suffit comme explication.", "*resserre le cuir enroulé autour de la poignée; serre les dents et raidit les épaules sous l'armure.*" },
        DISARM = { "L'honneur se gagne en actes, pas en discours. Jolie épée. Puis-je la voir un instant ?", "*resserre le cuir enroulé autour de la poignée; tente d'arracher l'arme adverse d'une brève torsion.*", "Ma hache connaît la vérité sur les fanfarons. Voyons si vous êtes aussi bavard sans arme.", "*frappe du poing un ancien symbole de clan; tente de saisir le bras armé et de détourner le manche hors de sa ligne.*" },
        INTIMIDATING_SHOUT = { "Que chaque guerrier du clan entende ma voix ! Fuyez tant que vous connaissez encore la route !", "*frappe du poing un ancien symbole de clan; lance un rugissement féroce au-dessus des têtes ennemies.*", "Un guerrier sans responsabilité n'est qu'un sot bruyant. C'était mon avertissement poli. Le prochain sera d'acier.", "*découvre les défenses dans un sourire décidé; frappe le bouclier et découvre les dents.*" },
        CHALLENGING_SHOUT = { "Que chaque guerrier du clan entende ma voix ! TOUS SUR MOI ! J'ai de la place pour toutes vos rancunes !", "*découvre les défenses dans un sourire décidé; écarte les bras et défie la ligne entière.*", "Que les ancêtres voient qui je suis dans ma façon de tenir. Laissez les autres ! Aujourd'hui, je suis votre problème !", "*ancre les pieds dans la terre retournée; martèle son bouclier et hurle aux assaillants.*" },
        SLAM = { "L'honneur se gagne en actes, pas en discours. Ce n'est pas un marteau. Vous ne sentirez guère la différence.", "*ancre les pieds dans la terre retournée; lève son arme au-dessus de l'épaule et l'abat de tout son poids.*", "Je ne laisserai pas les autres tenir seuls devant moi. Un coup net vaut cinq coups timides.", "*passe le pouce sur une entaille du manche de son arme; suspend un instant le mouvement, puis frappe lourdement.*" },
        DEVASTATE = { "L'honneur se gagne en actes, pas en discours. Déjà desserré ? Terminons le travail.", "*passe le pouce sur une entaille du manche de son arme; frappe une section d'armure déjà fragilisée.*", "Ma hache connaît la vérité sur les fanfarons. Votre forgeron a visiblement économisé au mauvais endroit.", "*laisse échapper un souffle rauque; tapote une jointure découverte, puis frappe de nouveau.*" },
        SHIELD_SLAM = { "L'honneur se gagne en actes, pas en discours. Un bouclier ferme aussi les portes. Souvent à hauteur de visage.", "*laisse échapper un souffle rauque; arrache le bouclier de sa garde et projette le bord en avant.*", "Un guerrier sans responsabilité n'est qu'un sot bruyant. Qui a prétendu que la défense devait être polie ?", "*resserre le cuir enroulé autour de la poignée; bondit d'un pas et laisse parler son bouclier.*" },
        CONCUSSION_BLOW = { "L'honneur se gagne en actes, pas en discours. Je vais essayer de vous déconcentrer.", "*resserre le cuir enroulé autour de la poignée; tente de porter un coup lourd entre deux mouvements adverses.*", "Que les ancêtres voient qui je suis dans ma façon de tenir. Je vais essayer d’offrir un instant de silence à tout le monde.", "*frappe du poing un ancien symbole de clan; raccourcit sa prise et tente de frapper avec une force surprenante.*" },
        VICTORY_RUSH = { "Le courage n'attend pas le second appel. Un de moins. Les autres tiennent encore debout.", "*frappe du poing un ancien symbole de clan; profite de son regain d'énergie pour repartir à l'assaut.*", "Je ne laisserai pas les autres tenir seuls devant moi. Nous fêterons cela plus tard. Quelque chose bouge encore.", "*découvre les défenses dans un sourire décidé; se frappe une fois la poitrine et avance aussitôt.*" },
        BATTLE_STANCE = { "Les ancêtres ne louent pas une victoire achetée par la sottise. Deux pieds bien placés séparent le courage de la sottise.", "*découvre les défenses dans un sourire décidé; plante les pieds à largeur d'épaules et fait rouler sa lame.*", "Ma hache connaît la vérité sur les fanfarons. Je reste prêt. Au reste du monde de décider.", "*ancre les pieds dans la terre retournée; répartit son poids entre le bras de bouclier et la main armée.*" },
        DEFENSIVE_STANCE = { "Une ligne brisée est un devoir trahi. Pour atteindre les miens, il faudra convaincre mon bouclier.", "*ancre les pieds dans la terre retournée; élargit ses appuis et lève le bouclier devant ses alliés.*", "Un guerrier sans responsabilité n'est qu'un sot bruyant. Ce n'est pas le cri le plus fort qui gagnera aujourd'hui.", "*passe le pouce sur une entaille du manche de son arme; abaisse son centre de gravité et devient un mur derrière sa garde.*" },
        BERSERKER_STANCE = { "Ma colère brûle. Mon intention reste claire. Qui a dit que la colère rend aveugle n'a jamais vraiment regardé.", "*passe le pouce sur une entaille du manche de son arme; inspire profondément et prend une posture féroce.*", "Que les ancêtres voient qui je suis dans ma façon de tenir. Le monde est soudain très simple : en avant.", "*laisse échapper un souffle rauque; relâche les épaules, abaisse son arme, puis la relève vivement.*" },
        PIERCING_HOWL = { "Que chaque guerrier du clan entende ma voix ! Si vous m'entendez, c'est déjà trop tard.", "*laisse échapper un souffle rauque; pousse un hurlement qui perce tout le vacarme alentour.*", "Je ne laisserai pas les autres tenir seuls devant moi. Non, ce n'était pas une meute de loups. Seulement moi.", "*resserre le cuir enroulé autour de la poignée; renverse la tête et laisse monter un long cri rauque.*" },
        SPEARING_STRIKE = { "L'honneur se gagne en actes, pas en discours. La brèche est étroite. Ma pointe ne l'est pas.", "*resserre le cuir enroulé autour de la poignée; avance droit devant, l'arme tendue.*", "Ma hache connaît la vérité sur les fanfarons. L'armure est solide. Les angles sont plus forts.", "*frappe du poing un ancien symbole de clan; tourne le poignet vers la faille et pousse la pointe.*" },
        TACTICAL_MASTERY = { "Les ancêtres ne louent pas une victoire achetée par la sottise. Entre le courage et la sottise, il y a de bons appuis.", "*frappe du poing un ancien symbole de clan; ajuste sa position d'un rien et garde le champ de bataille en vue.*", "Un guerrier sans responsabilité n'est qu'un sot bruyant. Un champ de bataille ne se joue pas aux dés. Il se lit.", "*découvre les défenses dans un sourire décidé; observe les chemins, les ennemis et les retraites sans abaisser son arme.*" },
