        DEMORALIZING_SHOUT = { "Les ancêtres écoutent, alors faites du bruit ! Les premiers tremblent déjà. Les derniers suivront !", "*touche un petit talisman à sa ceinture; pousse un cri profond et rugueux du fond de la poitrine.*", "Encore une bonne histoire pour plus tard, héhé. Regardez autour de vous. Pour qui vous battez-vous encore ?", "*se balance au rythme d'un tambour imaginaire; désigne de sa lame les lignes ennemies vacillantes.*" },
        REVENGE = { "Pourvu que les loa regardent, ça va devenir vivant. Merci pour l'occasion. Je vous la rends aussitôt.", "*se balance au rythme d'un tambour imaginaire; dévie une arme et frappe dans la brèche.*", "Quand les loa sourient, je leur souris aussi. J'oublie les visages. Jamais les coups.", "*passe le pouce sur un ancien signe gravé; passe directement de la parade à la riposte.*" },
        OVERPOWER = { "Pourvu que les loa regardent, ça va devenir vivant. Voilà une faille. Comme c'est généreux de votre part.", "*passe le pouce sur un ancien signe gravé; esquive le coup manqué et saisit l'angle ouvert.*", "Certains appellent ça de la chance. Moi, de l'entraînement. Manquez-moi une fois, vous m'invitez à entrer.", "*affiche un sourire de travers et avance son poids; transforme un faux pas adverse en riposte éclair.*" },
        MORTAL_STRIKE = { "Pourvu que les loa regardent, ça va devenir vivant. Je ne garde rien pour une seconde tentative.", "*affiche un sourire de travers et avance son poids; saisit son arme à deux mains et engage tout son poids.*", "Les ancêtres voient tout, surtout les erreurs comiques. Certains duels se règlent en paroles. Pas celui-ci.", "*tapote un rythme vif de deux doigts; avance et conduit l'acier avec une précision implacable.*" },
        WHIRLWIND = { "Le vieux féticheur en aurait bien ri. Mettez-vous donc en cercle. Cela m'arrange.", "*tapote un rythme vif de deux doigts; tourne dans la mêlée, l'arme tendue à bout de bras.*", "Encore une bonne histoire pour plus tard, héhé. J'aime partager. Aujourd'hui, c'est de l'acier.", "*sort une perle d'os cachée sous son armure; fait chanter la lame dans un large mouvement circulaire.*" },
        BLOODTHIRST = { "Le tambour dans ma poitrine bat plus vite aujourd'hui. Le pouls s'emballe. La main reste sûre.", "*sort une perle d'os cachée sous son armure; expire brusquement et poursuit son assaut sans relâche.*", "Quand les loa sourient, je leur souris aussi. La colère ne rend pas mes coups imprécis.", "*touche un petit talisman à sa ceinture; se rue en avant, les yeux sauvages, la prise parfaitement mesurée.*" },
        INTERCEPT = { "Pas si vite, mon. J'arrive !", "*touche un petit talisman à sa ceinture; jaillit de la mêlée et coupe toute retraite.*", "Certains appellent ça de la chance. Moi, de l'entraînement. Vous courez ? Parfait, j'avais besoin d'exercice.", "*se balance au rythme d'un tambour imaginaire; bondit de sa position et atterrit sur le chemin de la fuite.*" },
        PUMMEL = { "Pourvu que les loa regardent, ça va devenir vivant. Trop de paroles. Pas assez de garde.", "*se balance au rythme d'un tambour imaginaire; rompt le geste d'incantation d'un coup sec et précis.*", "Les ancêtres voient tout, surtout les erreurs comiques. Vous vouliez ajouter quelque chose ? Non ? Bien.", "*passe le pouce sur un ancien signe gravé; désorganise le mouvement du bras d'un petit coup.*" },
        SWEEPING_STRIKES = { "Le vieux féticheur en aurait bien ri. Pourquoi faire la moitié du travail quand toute une bataille nous attend ?", "*passe le pouce sur un ancien signe gravé; prolonge le premier coup en un second arc fluide.*", "Encore une bonne histoire pour plus tard, héhé. Plus d'ennemis ? Moins de déplacements.", "*affiche un sourire de travers et avance son poids; poursuit le mouvement de la lame à travers la mêlée.*" },
        DEATH_WISH = { "Le tambour dans ma poitrine bat plus vite aujourd'hui. La raison a donné son avis. Je ne suis pas d'accord.", "*affiche un sourire de travers et avance son poids; relâche un instant sa prise et choisit l'attaque.*", "Quand les loa sourient, je leur souris aussi. Je connais le risque. Eux, peut-être pas.", "*tapote un rythme vif de deux doigts; jette un dernier regard à sa garde avant de bondir.*" },
        RECKLESSNESS = { "Le tambour dans ma poitrine bat plus vite aujourd'hui. La prudence, c'était hier. Aujourd'hui, on agit.", "*tapote un rythme vif de deux doigts; rejette l'hésitation sans lâcher son arme.*", "Certains appellent ça de la chance. Moi, de l'entraînement. Vous pourrez me faire la morale demain. S'il y a un demain.", "*sort une perle d'os cachée sous son armure; engage tout son corps dans une suite de coups furieux.*" },
        LAST_STAND = { "Même un troll sait quand rester ferme. Jusqu'ici. Pas un pas de plus.", "*sort une perle d'os cachée sous son armure; se relève péniblement et lève de nouveau le bouclier.*", "Les ancêtres voient tout, surtout les erreurs comiques. Je tiens encore debout. Voilà ma réponse.", "*touche un petit talisman à sa ceinture; replace ses jambes tremblantes dans la brèche.*" },
        SHIELD_WALL = { "Même un troll sait quand rester ferme. Derrière moi ! Pas d'héroïsme solitaire !", "*touche un petit talisman à sa ceinture; ramène le bouclier contre soi et serre la ligne alliée.*", "Encore une bonne histoire pour plus tard, héhé. Qui veut passer devra avoir de la patience.", "*se balance au rythme d'un tambour imaginaire; ferme la dernière brèche entre le bouclier et l'armure.*" },
        RETALIATION = { "Pourvu que les loa regardent, ça va devenir vivant. Qui frappe doit apprécier l'écho.", "*se balance au rythme d'un tambour imaginaire; entrouvre la garde et répond à chaque coup par l'acier.*", "Quand les loa sourient, je leur souris aussi. Venez donc. J'ai un instant pour chacun.", "*passe le pouce sur un ancien signe gravé; ancre les pieds et attend les coups impatients.*" },
        MOCKING_BLOW = { "Héhé ! C'était votre meilleur coup ? Les loa vont rire.", "*passe le pouce sur un ancien signe gravé; abaisse trop ostensiblement la pointe et attire l'ennemi.*", "Certains appellent ça de la chance. Moi, de l'entraînement. Pardon. Je vous ai pris pour un mannequin d'entraînement.", "*affiche un sourire de travers et avance son poids; porte une petite taille insolente et sourit au-dessus du bouclier.*" },
        BERSERKER_RAGE = { "Le tambour dans ma poitrine bat plus vite aujourd'hui. La peur ? Pas de place pour elle aujourd'hui.", "*affiche un sourire de travers et avance son poids; roule les épaules comme pour se débarrasser d'un poids invisible.*", "Les ancêtres voient tout, surtout les erreurs comiques. La peur peut attendre dehors. Ma fureur entre.", "*tapote un rythme vif de deux doigts; expire brutalement et fixe le combat sans ciller.*" },
        BLOODRAGE = { "Le tambour dans ma poitrine bat plus vite aujourd'hui. La douleur est un message. Je répondrai plus tard.", "*tapote un rythme vif de deux doigts; frappe son torse du poing et rassemble son ardeur.*", "Encore une bonne histoire pour plus tard, héhé. Le cœur bat encore. Cela suffit comme explication.", "*sort une perle d'os cachée sous son armure; serre les dents et raidit les épaules sous l'armure.*" },
        DISARM = { "Pourvu que les loa regardent, ça va devenir vivant. Jolie épée. Puis-je la voir un instant ?", "*sort une perle d'os cachée sous son armure; tente d'arracher l'arme adverse d'une brève torsion.*", "Quand les loa sourient, je leur souris aussi. Voyons si vous êtes aussi bavard sans arme.", "*touche un petit talisman à sa ceinture; tente de saisir le bras armé et de détourner le manche hors de sa ligne.*" },
        INTIMIDATING_SHOUT = { "Les ancêtres écoutent, alors faites du bruit ! Fuyez tant que vous connaissez encore la route !", "*touche un petit talisman à sa ceinture; lance un rugissement féroce au-dessus des têtes ennemies.*", "Certains appellent ça de la chance. Moi, de l'entraînement. C'était mon avertissement poli. Le prochain sera d'acier.", "*se balance au rythme d'un tambour imaginaire; frappe le bouclier et découvre les dents.*" },
        CHALLENGING_SHOUT = { "Les ancêtres écoutent, alors faites du bruit ! TOUS SUR MOI ! J'ai de la place pour toutes vos rancunes !", "*se balance au rythme d'un tambour imaginaire; écarte les bras et défie la ligne entière.*", "Les ancêtres voient tout, surtout les erreurs comiques. Laissez les autres ! Aujourd'hui, je suis votre problème !", "*passe le pouce sur un ancien signe gravé; martèle son bouclier et hurle aux assaillants.*" },
        SLAM = { "Pourvu que les loa regardent, ça va devenir vivant. Ce n'est pas un marteau. Vous ne sentirez guère la différence.", "*passe le pouce sur un ancien signe gravé; lève son arme au-dessus de l'épaule et l'abat de tout son poids.*", "Encore une bonne histoire pour plus tard, héhé. Un coup net vaut cinq coups timides.", "*affiche un sourire de travers et avance son poids; suspend un instant le mouvement, puis frappe lourdement.*" },
        DEVASTATE = { "Pourvu que les loa regardent, ça va devenir vivant. Déjà desserré ? Terminons le travail.", "*affiche un sourire de travers et avance son poids; frappe une section d'armure déjà fragilisée.*", "Quand les loa sourient, je leur souris aussi. Votre forgeron a visiblement économisé au mauvais endroit.", "*tapote un rythme vif de deux doigts; tapote une jointure découverte, puis frappe de nouveau.*" },
        SHIELD_SLAM = { "Pourvu que les loa regardent, ça va devenir vivant. Un bouclier ferme aussi les portes. Souvent à hauteur de visage.", "*tapote un rythme vif de deux doigts; arrache le bouclier de sa garde et projette le bord en avant.*", "Certains appellent ça de la chance. Moi, de l'entraînement. Qui a prétendu que la défense devait être polie ?", "*sort une perle d'os cachée sous son armure; bondit d'un pas et laisse parler son bouclier.*" },
        CONCUSSION_BLOW = { "Pourvu que les loa regardent, ça va devenir vivant. Je vais essayer de vous déconcentrer.", "*sort une perle d'os cachée sous son armure; tente de porter un coup lourd entre deux mouvements adverses.*", "Les ancêtres voient tout, surtout les erreurs comiques. Je vais essayer d’offrir un instant de silence à tout le monde.", "*touche un petit talisman à sa ceinture; raccourcit sa prise et tente de frapper avec une force surprenante.*" },
        VICTORY_RUSH = { "Héhé ! Un pour les ancêtres, le prochain pour moi !", "*touche un petit talisman à sa ceinture; profite de son regain d'énergie pour repartir à l'assaut.*", "Encore une bonne histoire pour plus tard, héhé. Nous fêterons cela plus tard. Quelque chose bouge encore.", "*se balance au rythme d'un tambour imaginaire; se frappe une fois la poitrine et avance aussitôt.*" },
        BATTLE_STANCE = { "Le vieux féticheur en aurait bien ri. Deux pieds bien placés séparent le courage de la sottise.", "*se balance au rythme d'un tambour imaginaire; plante les pieds à largeur d'épaules et fait rouler sa lame.*", "Quand les loa sourient, je leur souris aussi. Je reste prêt. Au reste du monde de décider.", "*passe le pouce sur un ancien signe gravé; répartit son poids entre le bras de bouclier et la main armée.*" },
        DEFENSIVE_STANCE = { "Même un troll sait quand rester ferme. Pour atteindre les miens, il faudra convaincre mon bouclier.", "*passe le pouce sur un ancien signe gravé; élargit ses appuis et lève le bouclier devant ses alliés.*", "Certains appellent ça de la chance. Moi, de l'entraînement. Ce n'est pas le cri le plus fort qui gagnera aujourd'hui.", "*affiche un sourire de travers et avance son poids; abaisse son centre de gravité et devient un mur derrière sa garde.*" },
        BERSERKER_STANCE = { "Le tambour dans ma poitrine bat plus vite aujourd'hui. Qui a dit que la colère rend aveugle n'a jamais vraiment regardé.", "*affiche un sourire de travers et avance son poids; inspire profondément et prend une posture féroce.*", "Les ancêtres voient tout, surtout les erreurs comiques. Le monde est soudain très simple : en avant.", "*tapote un rythme vif de deux doigts; relâche les épaules, abaisse son arme, puis la relève vivement.*" },
        PIERCING_HOWL = { "Ce n'était pas un loup, mon. Juste mon chant du matin.", "*tapote un rythme vif de deux doigts; pousse un hurlement qui perce tout le vacarme alentour.*", "Encore une bonne histoire pour plus tard, héhé. Non, ce n'était pas une meute de loups. Seulement moi.", "*sort une perle d'os cachée sous son armure; renverse la tête et laisse monter un long cri rauque.*" },
        SPEARING_STRIKE = { "Pourvu que les loa regardent, ça va devenir vivant. La brèche est étroite. Ma pointe ne l'est pas.", "*sort une perle d'os cachée sous son armure; avance droit devant, l'arme tendue.*", "Quand les loa sourient, je leur souris aussi. L'armure est solide. Les angles sont plus forts.", "*touche un petit talisman à sa ceinture; tourne le poignet vers la faille et pousse la pointe.*" },
        TACTICAL_MASTERY = { "Le vieux féticheur en aurait bien ri. Entre le courage et la sottise, il y a de bons appuis.", "*touche un petit talisman à sa ceinture; ajuste sa position d'un rien et garde le champ de bataille en vue.*", "Certains appellent ça de la chance. Moi, de l'entraînement. Un champ de bataille ne se joue pas aux dés. Il se lit.", "*se balance au rythme d'un tambour imaginaire; observe les chemins, les ennemis et les retraites sans abaisser son arme.*" },
    },
    TAUREN = {
        HEROIC_STRIKE = { "Le tonnerre vient sans haine. Que mon coup lui ressemble. Vous savez pourquoi cette arme est lourde ? Elle discute rarement.", "*abaisse les cornes avec un calme grave; porte son poids vers l'avant et abat son arme avec vigueur.*", "La Terre-Mère connaît mes raisons. Certains arguments n'ont pas besoin de seconde phrase.", "*ancre ses deux sabots dans la terre; engage l'épaule et laisse l'acier finir la démonstration.*" },
        CHARGE = { "Quand le troupeau avance, aucune clôture ne le retient. Si le chemin est fermé, je prends la ligne droite.", "*ancre ses deux sabots dans la terre; baisse l'épaule et s'élance dans un nuage de poussière.*", "La force appartient à ceux qui protègent les autres. J'arrive ! Ce n'est pas une menace, c'est un itinéraire !", "*touche une tresse souvenir sur le manche de son arme; traverse une brèche dans un fracas d'armure.*" },
        REND = { "Le tonnerre vient sans haine. Que mon coup lui ressemble. Les coutures des armures cachent de petits secrets. Je suis curieux.", "*touche une tresse souvenir sur le manche de son arme; fait glisser sa lame dans une ouverture de la garde.*", "Mon souffle reste calme. Le sol sous moi, non. Un tailleur serait scandalisé. Moi, je suis ravi.", "*respire lentement par les naseaux; retire sa lame et cherche une nouvelle faille.*" },
        HAMSTRING = { "Le tonnerre vient sans haine. Que mon coup lui ressemble. Vous enfuir ? Voilà un plan bien fragile.", "*respire lentement par les naseaux; se baisse vivement sous la garde adverse.*", "Qui connaît les plaines sait quand tenir fermement. Je n'aime pas courir deux fois. Une fois suffit.", "*incline un instant la tête vers le sol; fauche bas et reprend immédiatement sa garde.*" },
        THUNDER_CLAP = { "Le tonnerre se souvient de chaque pas sur la plaine.", "*incline un instant la tête vers le sol; frappe si fort du pied que la poussière bondit.*", "La Terre-Mère connaît mes raisons. Vous entendez ? Même la terre proteste.", "*redresse un bandeau décoré de plumes; écarte les bras et laisse une onde sourde courir parmi les rangs.*" },
        CLEAVE = { "La hâte n'est pas la détermination. Si vous venez côte à côte, vous partagerez les ennuis.", "*redresse un bandeau décoré de plumes; décrit un vaste arc avec son arme dans la mêlée.*", "La force appartient à ceux qui protègent les autres. J'espère que vous avez gardé assez de place. Pas moi.", "*abaisse les cornes avec un calme grave; pivote sur un talon et prolonge l'élan d'un second mouvement.*" },
        EXECUTE = { "Le tonnerre vient sans haine. Que mon coup lui ressemble. Je vous ai laissé toutes les occasions de battre en retraite.", "*abaisse les cornes avec un calme grave; attend un battement de cœur, puis abat un coup décisif.*", "Mon souffle reste calme. Le sol sous moi, non. Les négociations sont terminées.", "*ancre ses deux sabots dans la terre; resserre sa prise et referme la dernière ouverture.*" },
        SUNDER_ARMOR = { "Le tonnerre vient sans haine. Que mon coup lui ressemble. Belle cuirasse. Dommage pour les rivets.", "*ancre ses deux sabots dans la terre; place le tranchant contre une jointure d'armure.*", "Qui connaît les plaines sait quand tenir fermement. Un acier coûteux ne remplace pas une bonne garde.", "*touche une tresse souvenir sur le manche de son arme; trace du fil de la lame une ligne entre deux plaques.*" },
        SHIELD_BLOCK = { "La montagne ne cède pas au premier orage. Il faudra frapper à la porte. Mon bouclier reste fermé.", "*touche une tresse souvenir sur le manche de son arme; tourne le bord du bouclier pour recevoir le coup.*", "La Terre-Mère connaît mes raisons. Un bon bouclier écoute avant de répondre.", "*respire lentement par les naseaux; plante ses bottes au sol sans céder un pouce.*" },
