        LAST_STAND = { "Tant que la terre me porte, elle porte mon serment.", "*redresse un bandeau décoré de plumes; se relève péniblement et lève de nouveau le bouclier.*", "Qui connaît les plaines sait quand tenir fermement. Je tiens encore debout. Voilà ma réponse.", "*abaisse les cornes avec un calme grave; replace ses jambes tremblantes dans la brèche.*" },
        SHIELD_WALL = { "Derrière mon bouclier, les jeunes pourront respirer demain.", "*abaisse les cornes avec un calme grave; ramène le bouclier contre soi et serre la ligne alliée.*", "La Terre-Mère connaît mes raisons. Qui veut passer devra avoir de la patience.", "*ancre ses deux sabots dans la terre; ferme la dernière brèche entre le bouclier et l'armure.*" },
        RETALIATION = { "Le tonnerre vient sans haine. Que mon coup lui ressemble. Qui frappe doit apprécier l'écho.", "*ancre ses deux sabots dans la terre; entrouvre la garde et répond à chaque coup par l'acier.*", "La force appartient à ceux qui protègent les autres. Venez donc. J'ai un instant pour chacun.", "*touche une tresse souvenir sur le manche de son arme; ancre les pieds et attend les coups impatients.*" },
        MOCKING_BLOW = { "Le tonnerre vient sans haine. Que mon coup lui ressemble. Vous êtes dangereux ou simplement bruyant ?", "*touche une tresse souvenir sur le manche de son arme; abaisse trop ostensiblement la pointe et attire l'ennemi.*", "Mon souffle reste calme. Le sol sous moi, non. Pardon. Je vous ai pris pour un mannequin d'entraînement.", "*respire lentement par les naseaux; porte une petite taille insolente et sourit au-dessus du bouclier.*" },
        BERSERKER_RAGE = { "La prairie brûle parfois pour renaître. La peur ? Pas de place pour elle aujourd'hui.", "*respire lentement par les naseaux; roule les épaules comme pour se débarrasser d'un poids invisible.*", "Qui connaît les plaines sait quand tenir fermement. La peur peut attendre dehors. Ma fureur entre.", "*incline un instant la tête vers le sol; expire brutalement et fixe le combat sans ciller.*" },
        BLOODRAGE = { "La prairie brûle parfois pour renaître. La douleur est un message. Je répondrai plus tard.", "*incline un instant la tête vers le sol; frappe son torse du poing et rassemble son ardeur.*", "La Terre-Mère connaît mes raisons. Le cœur bat encore. Cela suffit comme explication.", "*redresse un bandeau décoré de plumes; serre les dents et raidit les épaules sous l'armure.*" },
        DISARM = { "Le tonnerre vient sans haine. Que mon coup lui ressemble. Jolie épée. Puis-je la voir un instant ?", "*redresse un bandeau décoré de plumes; tente d'arracher l'arme adverse d'une brève torsion.*", "La force appartient à ceux qui protègent les autres. Voyons si vous êtes aussi bavard sans arme.", "*abaisse les cornes avec un calme grave; tente de saisir le bras armé et de détourner le manche hors de sa ligne.*" },
        INTIMIDATING_SHOUT = { "Que le vent porte notre résolution sur les plaines. Fuyez tant que vous connaissez encore la route !", "*abaisse les cornes avec un calme grave; lance un rugissement féroce au-dessus des têtes ennemies.*", "Mon souffle reste calme. Le sol sous moi, non. C'était mon avertissement poli. Le prochain sera d'acier.", "*ancre ses deux sabots dans la terre; frappe le bouclier et découvre les dents.*" },
        CHALLENGING_SHOUT = { "Venez tous. La plaine a de la place, moi aussi.", "*ancre ses deux sabots dans la terre; écarte les bras et défie la ligne entière.*", "Qui connaît les plaines sait quand tenir fermement. Laissez les autres ! Aujourd'hui, je suis votre problème !", "*touche une tresse souvenir sur le manche de son arme; martèle son bouclier et hurle aux assaillants.*" },
        SLAM = { "Le tonnerre vient sans haine. Que mon coup lui ressemble. Ce n'est pas un marteau. Vous ne sentirez guère la différence.", "*touche une tresse souvenir sur le manche de son arme; lève son arme au-dessus de l'épaule et l'abat de tout son poids.*", "La Terre-Mère connaît mes raisons. Un coup net vaut cinq coups timides.", "*respire lentement par les naseaux; suspend un instant le mouvement, puis frappe lourdement.*" },
        DEVASTATE = { "Le tonnerre vient sans haine. Que mon coup lui ressemble. Déjà desserré ? Terminons le travail.", "*respire lentement par les naseaux; frappe une section d'armure déjà fragilisée.*", "La force appartient à ceux qui protègent les autres. Votre forgeron a visiblement économisé au mauvais endroit.", "*incline un instant la tête vers le sol; tapote une jointure découverte, puis frappe de nouveau.*" },
        SHIELD_SLAM = { "Le tonnerre vient sans haine. Que mon coup lui ressemble. Un bouclier ferme aussi les portes. Souvent à hauteur de visage.", "*incline un instant la tête vers le sol; arrache le bouclier de sa garde et projette le bord en avant.*", "Mon souffle reste calme. Le sol sous moi, non. Qui a prétendu que la défense devait être polie ?", "*redresse un bandeau décoré de plumes; bondit d'un pas et laisse parler son bouclier.*" },
        CONCUSSION_BLOW = { "Le tonnerre vient sans haine. Que mon coup lui ressemble. Je vais essayer de vous déconcentrer.", "*redresse un bandeau décoré de plumes; tente de porter un coup lourd entre deux mouvements adverses.*", "Qui connaît les plaines sait quand tenir fermement. Je vais essayer d’offrir un instant de silence à tout le monde.", "*abaisse les cornes avec un calme grave; raccourcit sa prise et tente de frapper avec une force surprenante.*" },
        VICTORY_RUSH = { "Quand le troupeau avance, aucune clôture ne le retient. Un de moins. Les autres tiennent encore debout.", "*abaisse les cornes avec un calme grave; profite de son regain d'énergie pour repartir à l'assaut.*", "La Terre-Mère connaît mes raisons. Nous fêterons cela plus tard. Quelque chose bouge encore.", "*ancre ses deux sabots dans la terre; se frappe une fois la poitrine et avance aussitôt.*" },
        BATTLE_STANCE = { "La hâte n'est pas la détermination. Deux pieds bien placés séparent le courage de la sottise.", "*ancre ses deux sabots dans la terre; plante les pieds à largeur d'épaules et fait rouler sa lame.*", "La force appartient à ceux qui protègent les autres. Je reste prêt. Au reste du monde de décider.", "*touche une tresse souvenir sur le manche de son arme; répartit son poids entre le bras de bouclier et la main armée.*" },
        DEFENSIVE_STANCE = { "La montagne ne cède pas au premier orage. Pour atteindre les miens, il faudra convaincre mon bouclier.", "*touche une tresse souvenir sur le manche de son arme; élargit ses appuis et lève le bouclier devant ses alliés.*", "Mon souffle reste calme. Le sol sous moi, non. Ce n'est pas le cri le plus fort qui gagnera aujourd'hui.", "*respire lentement par les naseaux; abaisse son centre de gravité et devient un mur derrière sa garde.*" },
        BERSERKER_STANCE = { "La prairie brûle parfois pour renaître. Qui a dit que la colère rend aveugle n'a jamais vraiment regardé.", "*respire lentement par les naseaux; inspire profondément et prend une posture féroce.*", "Qui connaît les plaines sait quand tenir fermement. Le monde est soudain très simple : en avant.", "*incline un instant la tête vers le sol; relâche les épaules, abaisse son arme, puis la relève vivement.*" },
        PIERCING_HOWL = { "Que le vent porte notre résolution sur les plaines. Si vous m'entendez, c'est déjà trop tard.", "*incline un instant la tête vers le sol; pousse un hurlement qui perce tout le vacarme alentour.*", "La Terre-Mère connaît mes raisons. Non, ce n'était pas une meute de loups. Seulement moi.", "*redresse un bandeau décoré de plumes; renverse la tête et laisse monter un long cri rauque.*" },
        SPEARING_STRIKE = { "Le tonnerre vient sans haine. Que mon coup lui ressemble. La brèche est étroite. Ma pointe ne l'est pas.", "*redresse un bandeau décoré de plumes; avance droit devant, l'arme tendue.*", "La force appartient à ceux qui protègent les autres. L'armure est solide. Les angles sont plus forts.", "*abaisse les cornes avec un calme grave; tourne le poignet vers la faille et pousse la pointe.*" },
        TACTICAL_MASTERY = { "La hâte n'est pas la détermination. Entre le courage et la sottise, il y a de bons appuis.", "*abaisse les cornes avec un calme grave; ajuste sa position d'un rien et garde le champ de bataille en vue.*", "Mon souffle reste calme. Le sol sous moi, non. Un champ de bataille ne se joue pas aux dés. Il se lit.", "*ancre ses deux sabots dans la terre; observe les chemins, les ennemis et les retraites sans abaisser son arme.*" },
    },
    UNDEAD = {
        HEROIC_STRIKE = { "J'ai connu pire. Ma mort, par exemple. Vous savez pourquoi cette arme est lourde ? Elle discute rarement.", "*remonte un gant sur ses doigts osseux; porte son poids vers l'avant et abat son arme avec vigueur.*", "On m'a cru fini. Plusieurs fois. Certains arguments n'ont pas besoin de seconde phrase.", "*penche la tête jusqu'à entendre un craquement; engage l'épaule et laisse l'acier finir la démonstration.*" },
        CHARGE = { "Plus vite que ma propre décomposition. Cela suffira. Si le chemin est fermé, je prends la ligne droite.", "*penche la tête jusqu'à entendre un craquement; baisse l'épaule et s'élance dans un nuage de poussière.*", "Mon dernier souffle ne fut pas mon dernier mot. J'arrive ! Ce n'est pas une menace, c'est un itinéraire !", "*redresse une couture de son vieux manteau; traverse une brèche dans un fracas d'armure.*" },
        REND = { "J'ai connu pire. Ma mort, par exemple. Les coutures des armures cachent de petits secrets. Je suis curieux.", "*redresse une couture de son vieux manteau; fait glisser sa lame dans une ouverture de la garde.*", "Les articulations qui craquent sont un avertissement poli. Un tailleur serait scandalisé. Moi, je suis ravi.", "*époussette une boucle rouillée; retire sa lame et cherche une nouvelle faille.*" },
        HAMSTRING = { "J'ai connu pire. Ma mort, par exemple. Vous enfuir ? Voilà un plan bien fragile.", "*époussette une boucle rouillée; se baisse vivement sous la garde adverse.*", "Je me souviens de mes erreurs. Certaines portent une armure. Je n'aime pas courir deux fois. Une fois suffit.", "*vérifie le bandage fragile d'une articulation; fauche bas et reprend immédiatement sa garde.*" },
        THUNDER_CLAP = { "J'ai connu pire. Ma mort, par exemple. Quand le sol tremble, plus besoin de tambour.", "*vérifie le bandage fragile d'une articulation; frappe si fort du pied que la poussière bondit.*", "On m'a cru fini. Plusieurs fois. Vous entendez ? Même la terre proteste.", "*laisse échapper un petit rire sec; écarte les bras et laisse une onde sourde courir parmi les rangs.*" },
        CLEAVE = { "Sans battement de cœur, on a du temps pour réfléchir. Si vous venez côte à côte, vous partagerez les ennuis.", "*laisse échapper un petit rire sec; décrit un vaste arc avec son arme dans la mêlée.*", "Mon dernier souffle ne fut pas mon dernier mot. J'espère que vous avez gardé assez de place. Pas moi.", "*remonte un gant sur ses doigts osseux; pivote sur un talon et prolonge l'élan d'un second mouvement.*" },
        EXECUTE = { "J'ai connu pire. Ma mort, par exemple. Je vous ai laissé toutes les occasions de battre en retraite.", "*remonte un gant sur ses doigts osseux; attend un battement de cœur, puis abat un coup décisif.*", "Les articulations qui craquent sont un avertissement poli. Les négociations sont terminées.", "*penche la tête jusqu'à entendre un craquement; resserre sa prise et referme la dernière ouverture.*" },
        SUNDER_ARMOR = { "J'ai connu pire. Ma mort, par exemple. Belle cuirasse. Dommage pour les rivets.", "*penche la tête jusqu'à entendre un craquement; place le tranchant contre une jointure d'armure.*", "Je me souviens de mes erreurs. Certaines portent une armure. Un acier coûteux ne remplace pas une bonne garde.", "*redresse une couture de son vieux manteau; trace du fil de la lame une ligne entre deux plaques.*" },
        SHIELD_BLOCK = { "Il est difficile d'effrayer quelqu'un déjà enterré. Il faudra frapper à la porte. Mon bouclier reste fermé.", "*redresse une couture de son vieux manteau; tourne le bord du bouclier pour recevoir le coup.*", "On m'a cru fini. Plusieurs fois. Un bon bouclier écoute avant de répondre.", "*époussette une boucle rouillée; plante ses bottes au sol sans céder un pouce.*" },
        SHIELD_BASH = { "J'ai connu pire. Ma mort, par exemple. Chut. Voyons si je peux interrompre votre sort.", "*époussette une boucle rouillée; pousse son bouclier en avant entre deux syllabes.*", "Mon dernier souffle ne fut pas mon dernier mot. Ma réponse à la magie possède une poignée de bois.", "*vérifie le bandage fragile d'une articulation; avance d'un pas et tente de percuter sans prévenir.*" },
        TAUNT = { "Vous voulez un cauchemar ? Je suis déjà sorti du lit.", "*vérifie le bandage fragile d'une articulation; frappe trois fois la poignée de son arme contre son bouclier.*", "Les articulations qui craquent sont un avertissement poli. Les autres sont occupés. Pas moi.", "*laisse échapper un petit rire sec; sort de la ligne et invite les ennemis à approcher.*" },
        BATTLE_SHOUT = { "Ma voix sonne creux. Pas ma menace. Têtes hautes, rangs serrés ! Personne ne tombe seul !", "*laisse échapper un petit rire sec; bat la mesure avec la poignée contre le bouclier.*", "Je me souviens de mes erreurs. Certaines portent une armure. Vous avez des jambes pour tenir et du cœur pour résister. Servez-vous-en !", "*remonte un gant sur ses doigts osseux; se dresse devant ses alliés et lève la lame.*" },
        DEMORALIZING_SHOUT = { "Ma voix sonne creux. Pas ma menace. Les premiers tremblent déjà. Les derniers suivront !", "*remonte un gant sur ses doigts osseux; pousse un cri profond et rugueux du fond de la poitrine.*", "On m'a cru fini. Plusieurs fois. Regardez autour de vous. Pour qui vous battez-vous encore ?", "*penche la tête jusqu'à entendre un craquement; désigne de sa lame les lignes ennemies vacillantes.*" },
        REVENGE = { "J'ai connu pire. Ma mort, par exemple. Merci pour l'occasion. Je vous la rends aussitôt.", "*penche la tête jusqu'à entendre un craquement; dévie une arme et frappe dans la brèche.*", "Mon dernier souffle ne fut pas mon dernier mot. J'oublie les visages. Jamais les coups.", "*redresse une couture de son vieux manteau; passe directement de la parade à la riposte.*" },
        OVERPOWER = { "J'ai connu pire. Ma mort, par exemple. Voilà une faille. Comme c'est généreux de votre part.", "*redresse une couture de son vieux manteau; esquive le coup manqué et saisit l'angle ouvert.*", "Les articulations qui craquent sont un avertissement poli. Manquez-moi une fois, vous m'invitez à entrer.", "*époussette une boucle rouillée; transforme un faux pas adverse en riposte éclair.*" },
        MORTAL_STRIKE = { "J'ai connu pire. Ma mort, par exemple. Je ne garde rien pour une seconde tentative.", "*époussette une boucle rouillée; saisit son arme à deux mains et engage tout son poids.*", "Je me souviens de mes erreurs. Certaines portent une armure. Certains duels se règlent en paroles. Pas celui-ci.", "*vérifie le bandage fragile d'une articulation; avance et conduit l'acier avec une précision implacable.*" },
        WHIRLWIND = { "Sans battement de cœur, on a du temps pour réfléchir. Mettez-vous donc en cercle. Cela m'arrange.", "*vérifie le bandage fragile d'une articulation; tourne dans la mêlée, l'arme tendue à bout de bras.*", "On m'a cru fini. Plusieurs fois. J'aime partager. Aujourd'hui, c'est de l'acier.", "*laisse échapper un petit rire sec; fait chanter la lame dans un large mouvement circulaire.*" },
        BLOODTHIRST = { "Ma patience est morte avec moi, il y a longtemps. Le pouls s'emballe. La main reste sûre.", "*laisse échapper un petit rire sec; expire brusquement et poursuit son assaut sans relâche.*", "Mon dernier souffle ne fut pas mon dernier mot. La colère ne rend pas mes coups imprécis.", "*remonte un gant sur ses doigts osseux; se rue en avant, les yeux sauvages, la prise parfaitement mesurée.*" },
        INTERCEPT = { "Plus vite que ma propre décomposition. Cela suffira. Une avance n'est qu'un temps emprunté.", "*remonte un gant sur ses doigts osseux; jaillit de la mêlée et coupe toute retraite.*", "Les articulations qui craquent sont un avertissement poli. Vous courez ? Parfait, j'avais besoin d'exercice.", "*penche la tête jusqu'à entendre un craquement; bondit de sa position et atterrit sur le chemin de la fuite.*" },
        PUMMEL = { "J'ai connu pire. Ma mort, par exemple. Trop de paroles. Pas assez de garde.", "*penche la tête jusqu'à entendre un craquement; rompt le geste d'incantation d'un coup sec et précis.*", "Je me souviens de mes erreurs. Certaines portent une armure. Vous vouliez ajouter quelque chose ? Non ? Bien.", "*redresse une couture de son vieux manteau; désorganise le mouvement du bras d'un petit coup.*" },
        SWEEPING_STRIKES = { "Sans battement de cœur, on a du temps pour réfléchir. Pourquoi faire la moitié du travail quand toute une bataille nous attend ?", "*redresse une couture de son vieux manteau; prolonge le premier coup en un second arc fluide.*", "On m'a cru fini. Plusieurs fois. Plus d'ennemis ? Moins de déplacements.", "*époussette une boucle rouillée; poursuit le mouvement de la lame à travers la mêlée.*" },
        DEATH_WISH = { "Ma patience est morte avec moi, il y a longtemps. La raison a donné son avis. Je ne suis pas d'accord.", "*époussette une boucle rouillée; relâche un instant sa prise et choisit l'attaque.*", "Mon dernier souffle ne fut pas mon dernier mot. Je connais le risque. Eux, peut-être pas.", "*vérifie le bandage fragile d'une articulation; jette un dernier regard à sa garde avant de bondir.*" },
