        BATTLE_STANCE = { "Sans battement de cœur, on a du temps pour réfléchir. Deux pieds bien placés séparent le courage de la sottise.", "*penche la tête jusqu'à entendre un craquement; plante les pieds à largeur d'épaules et fait rouler sa lame.*", "Mon dernier souffle ne fut pas mon dernier mot. Je reste prêt. Au reste du monde de décider.", "*redresse une couture de son vieux manteau; répartit son poids entre le bras de bouclier et la main armée.*" },
        DEFENSIVE_STANCE = { "Il est difficile d'effrayer quelqu'un déjà enterré. Pour atteindre les miens, il faudra convaincre mon bouclier.", "*redresse une couture de son vieux manteau; élargit ses appuis et lève le bouclier devant ses alliés.*", "Les articulations qui craquent sont un avertissement poli. Ce n'est pas le cri le plus fort qui gagnera aujourd'hui.", "*époussette une boucle rouillée; abaisse son centre de gravité et devient un mur derrière sa garde.*" },
        BERSERKER_STANCE = { "Ma patience est morte avec moi, il y a longtemps. Qui a dit que la colère rend aveugle n'a jamais vraiment regardé.", "*époussette une boucle rouillée; inspire profondément et prend une posture féroce.*", "Je me souviens de mes erreurs. Certaines portent une armure. Le monde est soudain très simple : en avant.", "*vérifie le bandage fragile d'une articulation; relâche les épaules, abaisse son arme, puis la relève vivement.*" },
        PIERCING_HOWL = { "Si seulement mes voisins pouvaient entendre ça. Ah, ils sont morts.", "*vérifie le bandage fragile d'une articulation; pousse un hurlement qui perce tout le vacarme alentour.*", "On m'a cru fini. Plusieurs fois. Non, ce n'était pas une meute de loups. Seulement moi.", "*laisse échapper un petit rire sec; renverse la tête et laisse monter un long cri rauque.*" },
        SPEARING_STRIKE = { "J'ai connu pire. Ma mort, par exemple. La brèche est étroite. Ma pointe ne l'est pas.", "*laisse échapper un petit rire sec; avance droit devant, l'arme tendue.*", "Mon dernier souffle ne fut pas mon dernier mot. L'armure est solide. Les angles sont plus forts.", "*remonte un gant sur ses doigts osseux; tourne le poignet vers la faille et pousse la pointe.*" },
        TACTICAL_MASTERY = { "Sans battement de cœur, on a du temps pour réfléchir. Entre le courage et la sottise, il y a de bons appuis.", "*remonte un gant sur ses doigts osseux; ajuste sa position d'un rien et garde le champ de bataille en vue.*", "Les articulations qui craquent sont un avertissement poli. Un champ de bataille ne se joue pas aux dés. Il se lit.", "*penche la tête jusqu'à entendre un craquement; observe les chemins, les ennemis et les retraites sans abaisser son arme.*" },
    },
    BLOODELF = {
        HEROIC_STRIKE = { "Un coup net a plus d'élégance que toutes les menaces. Vous savez pourquoi cette arme est lourde ? Elle discute rarement.", "*lisse une ride dans sa manche brodée; porte son poids vers l'avant et abat son arme avec vigueur.*", "Un geste maladroit me gênerait plus qu'une égratignure. Certains arguments n'ont pas besoin de seconde phrase.", "*ajuste une garde travaillée avec finesse; engage l'épaule et laisse l'acier finir la démonstration.*" },
        CHARGE = { "Le style n'oblige pas à la lenteur. Si le chemin est fermé, je prends la ligne droite.", "*ajuste une garde travaillée avec finesse; baisse l'épaule et s'élance dans un nuage de poussière.*", "Mes ancêtres critiqueraient la posture, jamais le courage. J'arrive ! Ce n'est pas une menace, c'est un itinéraire !", "*tourne le pommeau de son arme avec grâce; traverse une brèche dans un fracas d'armure.*" },
        REND = { "Un coup net a plus d'élégance que toutes les menaces. Les coutures des armures cachent de petits secrets. Je suis curieux.", "*tourne le pommeau de son arme avec grâce; fait glisser sa lame dans une ouverture de la garde.*", "La lame n'a besoin d'aucun ornement, juste du bon angle. Un tailleur serait scandalisé. Moi, je suis ravi.", "*relève le menton d'un angle presque imperceptible; retire sa lame et cherche une nouvelle faille.*" },
        HAMSTRING = { "Un coup net a plus d'élégance que toutes les menaces. Vous enfuir ? Voilà un plan bien fragile.", "*relève le menton d'un angle presque imperceptible; se baisse vivement sous la garde adverse.*", "Même dans le chaos, on peut préserver sa dignité. Je n'aime pas courir deux fois. Une fois suffit.", "*vérifie une broche d'épaule ouvragée; fauche bas et reprend immédiatement sa garde.*" },
        THUNDER_CLAP = { "Un coup net a plus d'élégance que toutes les menaces. Quand le sol tremble, plus besoin de tambour.", "*vérifie une broche d'épaule ouvragée; frappe si fort du pied que la poussière bondit.*", "Un geste maladroit me gênerait plus qu'une égratignure. Vous entendez ? Même la terre proteste.", "*guide sa lame d'un geste sobre du poignet; écarte les bras et laisse une onde sourde courir parmi les rangs.*" },
        CLEAVE = { "Un duel est de la géométrie avec des conséquences. Si vous venez côte à côte, vous partagerez les ennuis.", "*guide sa lame d'un geste sobre du poignet; décrit un vaste arc avec son arme dans la mêlée.*", "Mes ancêtres critiqueraient la posture, jamais le courage. J'espère que vous avez gardé assez de place. Pas moi.", "*lisse une ride dans sa manche brodée; pivote sur un talon et prolonge l'élan d'un second mouvement.*" },
        EXECUTE = { "Un coup net a plus d'élégance que toutes les menaces. Je vous ai laissé toutes les occasions de battre en retraite.", "*lisse une ride dans sa manche brodée; attend un battement de cœur, puis abat un coup décisif.*", "La lame n'a besoin d'aucun ornement, juste du bon angle. Les négociations sont terminées.", "*ajuste une garde travaillée avec finesse; resserre sa prise et referme la dernière ouverture.*" },
        SUNDER_ARMOR = { "Un coup net a plus d'élégance que toutes les menaces. Belle cuirasse. Dommage pour les rivets.", "*ajuste une garde travaillée avec finesse; place le tranchant contre une jointure d'armure.*", "Même dans le chaos, on peut préserver sa dignité. Un acier coûteux ne remplace pas une bonne garde.", "*tourne le pommeau de son arme avec grâce; trace du fil de la lame une ligne entre deux plaques.*" },
        SHIELD_BLOCK = { "Une belle tenue résiste mieux qu'une armure médiocre. Il faudra frapper à la porte. Mon bouclier reste fermé.", "*tourne le pommeau de son arme avec grâce; tourne le bord du bouclier pour recevoir le coup.*", "Un geste maladroit me gênerait plus qu'une égratignure. Un bon bouclier écoute avant de répondre.", "*relève le menton d'un angle presque imperceptible; plante ses bottes au sol sans céder un pouce.*" },
        SHIELD_BASH = { "Un coup net a plus d'élégance que toutes les menaces. Chut. Voyons si je peux interrompre votre sort.", "*relève le menton d'un angle presque imperceptible; pousse son bouclier en avant entre deux syllabes.*", "Mes ancêtres critiqueraient la posture, jamais le courage. Ma réponse à la magie possède une poignée de bois.", "*vérifie une broche d'épaule ouvragée; avance d'un pas et tente de percuter sans prévenir.*" },
        TAUNT = { "Un coup net a plus d'élégance que toutes les menaces. Par ici ! Les ennuis portent mon nom aujourd'hui.", "*vérifie une broche d'épaule ouvragée; frappe trois fois la poignée de son arme contre son bouclier.*", "La lame n'a besoin d'aucun ornement, juste du bon angle. Les autres sont occupés. Pas moi.", "*guide sa lame d'un geste sobre du poignet; sort de la ligne et invite les ennemis à approcher.*" },
        BATTLE_SHOUT = { "Même un message crié doit être formulé avec précision. Têtes hautes, rangs serrés ! Personne ne tombe seul !", "*guide sa lame d'un geste sobre du poignet; bat la mesure avec la poignée contre le bouclier.*", "Même dans le chaos, on peut préserver sa dignité. Vous avez des jambes pour tenir et du cœur pour résister. Servez-vous-en !", "*lisse une ride dans sa manche brodée; se dresse devant ses alliés et lève la lame.*" },
        DEMORALIZING_SHOUT = { "Même un message crié doit être formulé avec précision. Les premiers tremblent déjà. Les derniers suivront !", "*lisse une ride dans sa manche brodée; pousse un cri profond et rugueux du fond de la poitrine.*", "Un geste maladroit me gênerait plus qu'une égratignure. Regardez autour de vous. Pour qui vous battez-vous encore ?", "*ajuste une garde travaillée avec finesse; désigne de sa lame les lignes ennemies vacillantes.*" },
        REVENGE = { "Un coup net a plus d'élégance que toutes les menaces. Merci pour l'occasion. Je vous la rends aussitôt.", "*ajuste une garde travaillée avec finesse; dévie une arme et frappe dans la brèche.*", "Mes ancêtres critiqueraient la posture, jamais le courage. J'oublie les visages. Jamais les coups.", "*tourne le pommeau de son arme avec grâce; passe directement de la parade à la riposte.*" },
        OVERPOWER = { "Un coup net a plus d'élégance que toutes les menaces. Voilà une faille. Comme c'est généreux de votre part.", "*tourne le pommeau de son arme avec grâce; esquive le coup manqué et saisit l'angle ouvert.*", "La lame n'a besoin d'aucun ornement, juste du bon angle. Manquez-moi une fois, vous m'invitez à entrer.", "*relève le menton d'un angle presque imperceptible; transforme un faux pas adverse en riposte éclair.*" },
        MORTAL_STRIKE = { "Un coup net a plus d'élégance que toutes les menaces. Je ne garde rien pour une seconde tentative.", "*relève le menton d'un angle presque imperceptible; saisit son arme à deux mains et engage tout son poids.*", "Même dans le chaos, on peut préserver sa dignité. Certains duels se règlent en paroles. Pas celui-ci.", "*vérifie une broche d'épaule ouvragée; avance et conduit l'acier avec une précision implacable.*" },
        WHIRLWIND = { "Un duel est de la géométrie avec des conséquences. Mettez-vous donc en cercle. Cela m'arrange.", "*vérifie une broche d'épaule ouvragée; tourne dans la mêlée, l'arme tendue à bout de bras.*", "Un geste maladroit me gênerait plus qu'une égratignure. J'aime partager. Aujourd'hui, c'est de l'acier.", "*guide sa lame d'un geste sobre du poignet; fait chanter la lame dans un large mouvement circulaire.*" },
        BLOODTHIRST = { "La vraie maîtrise de soi se voit dans la colère. Le pouls s'emballe. La main reste sûre.", "*guide sa lame d'un geste sobre du poignet; expire brusquement et poursuit son assaut sans relâche.*", "Mes ancêtres critiqueraient la posture, jamais le courage. La colère ne rend pas mes coups imprécis.", "*lisse une ride dans sa manche brodée; se rue en avant, les yeux sauvages, la prise parfaitement mesurée.*" },
        INTERCEPT = { "Le style n'oblige pas à la lenteur. Une avance n'est qu'un temps emprunté.", "*lisse une ride dans sa manche brodée; jaillit de la mêlée et coupe toute retraite.*", "La lame n'a besoin d'aucun ornement, juste du bon angle. Vous courez ? Parfait, j'avais besoin d'exercice.", "*ajuste une garde travaillée avec finesse; bondit de sa position et atterrit sur le chemin de la fuite.*" },
        PUMMEL = { "Un coup net a plus d'élégance que toutes les menaces. Trop de paroles. Pas assez de garde.", "*ajuste une garde travaillée avec finesse; rompt le geste d'incantation d'un coup sec et précis.*", "Même dans le chaos, on peut préserver sa dignité. Vous vouliez ajouter quelque chose ? Non ? Bien.", "*tourne le pommeau de son arme avec grâce; désorganise le mouvement du bras d'un petit coup.*" },
        SWEEPING_STRIKES = { "Un duel est de la géométrie avec des conséquences. Pourquoi faire la moitié du travail quand toute une bataille nous attend ?", "*tourne le pommeau de son arme avec grâce; prolonge le premier coup en un second arc fluide.*", "Un geste maladroit me gênerait plus qu'une égratignure. Plus d'ennemis ? Moins de déplacements.", "*relève le menton d'un angle presque imperceptible; poursuit le mouvement de la lame à travers la mêlée.*" },
        DEATH_WISH = { "La vraie maîtrise de soi se voit dans la colère. La raison a donné son avis. Je ne suis pas d'accord.", "*relève le menton d'un angle presque imperceptible; relâche un instant sa prise et choisit l'attaque.*", "Mes ancêtres critiqueraient la posture, jamais le courage. Je connais le risque. Eux, peut-être pas.", "*vérifie une broche d'épaule ouvragée; jette un dernier regard à sa garde avant de bondir.*" },
        RECKLESSNESS = { "L'élégance parfaite ne signifie pas toujours la retenue.", "*vérifie une broche d'épaule ouvragée; rejette l'hésitation sans lâcher son arme.*", "La lame n'a besoin d'aucun ornement, juste du bon angle. Vous pourrez me faire la morale demain. S'il y a un demain.", "*guide sa lame d'un geste sobre du poignet; engage tout son corps dans une suite de coups furieux.*" },
        LAST_STAND = { "Une belle tenue résiste mieux qu'une armure médiocre. Jusqu'ici. Pas un pas de plus.", "*guide sa lame d'un geste sobre du poignet; se relève péniblement et lève de nouveau le bouclier.*", "Même dans le chaos, on peut préserver sa dignité. Je tiens encore debout. Voilà ma réponse.", "*lisse une ride dans sa manche brodée; replace ses jambes tremblantes dans la brèche.*" },
        SHIELD_WALL = { "Une belle tenue résiste mieux qu'une armure médiocre. Derrière moi ! Pas d'héroïsme solitaire !", "*lisse une ride dans sa manche brodée; ramène le bouclier contre soi et serre la ligne alliée.*", "Un geste maladroit me gênerait plus qu'une égratignure. Qui veut passer devra avoir de la patience.", "*ajuste une garde travaillée avec finesse; ferme la dernière brèche entre le bouclier et l'armure.*" },
        RETALIATION = { "Un coup net a plus d'élégance que toutes les menaces. Qui frappe doit apprécier l'écho.", "*ajuste une garde travaillée avec finesse; entrouvre la garde et répond à chaque coup par l'acier.*", "Mes ancêtres critiqueraient la posture, jamais le courage. Venez donc. J'ai un instant pour chacun.", "*tourne le pommeau de son arme avec grâce; ancre les pieds et attend les coups impatients.*" },
        MOCKING_BLOW = { "Pardonnez-moi, j'ai pris votre technique pour une représentation.", "*tourne le pommeau de son arme avec grâce; abaisse trop ostensiblement la pointe et attire l'ennemi.*", "La lame n'a besoin d'aucun ornement, juste du bon angle. Pardon. Je vous ai pris pour un mannequin d'entraînement.", "*relève le menton d'un angle presque imperceptible; porte une petite taille insolente et sourit au-dessus du bouclier.*" },
